// Two Truths & a Lie: who, the two truths, and [the lie, the correction]. References come from English.
export const KN_TWO_TRUTHS = [
  ["ಸಂಸೋನ",["ಕೈಯಲ್ಲಿ ಏನೂ ಇಲ್ಲದೆ ಪ್ರಾಯದ ಸಿಂಹವನ್ನು ಕೊಂದನು.","ಹುಟ್ಟಿನಿಂದಲೇ ಅವನು ದೇವರಿಗೆ ನಾಜೀರನಾಗಿದ್ದನು."],["ದೆಲೀಲಳು ಮೂವತ್ತು ಬೆಳ್ಳಿ ನಾಣ್ಯಗಳಿಗಾಗಿ ಅವನನ್ನು ಹಿಡಿದುಕೊಟ್ಟಳು.","ಫಿಲಿಷ್ಟಿಯರ ಪ್ರತಿಯೊಬ್ಬ ಅಧಿಪತಿ ಅವಳಿಗೆ 1,100 ಬೆಳ್ಳಿ ನಾಣ್ಯ ಕೊಡುವೆವೆಂದರು."]],
  ["ಮೋಶೆ",["ಮಗುವಾಗಿದ್ದಾಗ ಆಪಿನ ಪೆಟ್ಟಿಗೆಯಲ್ಲಿ ಅಡಗಿಸಲ್ಪಟ್ಟನು.","ಅವನ ಪರವಾಗಿ ಅವನ ಸಹೋದರ ಆರೋನನು ಜನರೊಂದಿಗೆ ಮಾತನಾಡಿದನು."],["ಅವನು ಜನರನ್ನು ವಾಗ್ದತ್ತ ದೇಶದೊಳಗೆ ನಡೆಸಿದನು.","ಅವನು ನೆಬೋ ಬೆಟ್ಟದಿಂದ ಅದನ್ನು ನೋಡಿದನು; ಯೆಹೋಶುವನು ಅವರನ್ನು ಒಳಗೆ ನಡೆಸಿದನು."]],
  ["ದಾವೀದ",["ಅವನು ಇಷಯನ ಕಿರಿಯ ಮಗ.","ಅರಸನಾದ ಸೌಲನಿಗಾಗಿ ಕಿನ್ನರಿ ಬಾರಿಸಿದನು."],["ಯೆರೂಸಲೇಮಿನಲ್ಲಿ ದೇವಾಲಯವನ್ನು ಕಟ್ಟಿದನು.","ಅವನ ಮಗ ಸೊಲೊಮೋನನು ಅದನ್ನು ಕಟ್ಟಿದನು."]],
  ["ನೋಹ",["ಅವನಿಗೆ ಶೇಮ್, ಹಾಮ್, ಯೆಫೆತ್ ಎಂಬ ಮೂವರು ಮಕ್ಕಳಿದ್ದರು.","ನಾವೆಯಿಂದ ಒಂದು ಕಾಗೆಯನ್ನೂ ಒಂದು ಪಾರಿವಾಳವನ್ನೂ ಹೊರಗೆ ಬಿಟ್ಟನು."],["ಏಳು ದಿನ ಹಗಲು ರಾತ್ರಿ ಮಳೆ ಸುರಿಯಿತು.","ನಾಲ್ವತ್ತು ದಿನ ಹಗಲು ರಾತ್ರಿ ಮಳೆ ಸುರಿಯಿತು."]],
  ["ಯೋನ",["ತಾರ್ಷೀಷಿಗೆ ಓಡಿಹೋಗಲು ಪ್ರಯತ್ನಿಸಿದನು.","ಮೂರು ದಿನ ಹಗಲು ರಾತ್ರಿ ಮೀನಿನ ಹೊಟ್ಟೆಯಲ್ಲಿದ್ದನು."],["ನಿನೆವೆಯು ಮಾನಸಾಂತರಪಡಲು ನಿರಾಕರಿಸಿತು.","ನಿನೆವೆಯವರು ತಮ್ಮ ದುರ್ಮಾರ್ಗವನ್ನು ಬಿಟ್ಟರು; ದೇವರು ಪಟ್ಟಣವನ್ನು ಉಳಿಸಿದನು."]],
  ["ದಾನಿಯೇಲ",["ಯೌವನದಲ್ಲಿ ಬಾಬೆಲಿಗೆ ಒಯ್ಯಲ್ಪಟ್ಟನು.","ದಿನಕ್ಕೆ ಮೂರು ಸಾರಿ ಪ್ರಾರ್ಥಿಸುತ್ತಿದ್ದನು."],["ಉರಿಯುವ ಕುಲುಮೆಯಲ್ಲಿ ಹಾಕಲ್ಪಟ್ಟನು.","ಅದು ಶದ್ರಕ್, ಮೇಷಕ್, ಅಬೇದ್‌ನೆಗೋ."]],
  ["ಎಸ್ತೇರ",["ಅವಳ ದೊಡ್ಡಪ್ಪನ ಮಗನಾದ ಮೊರ್ದೆಕೈ ಅವಳನ್ನು ಬೆಳೆಸಿದನು.","ಅವಳು ರಾಣಿಯಾದಳು."],["ಅವಳ ಗಂಡ ಅರಸನಾದ ನೆಬೂಕದ್ನೆಚ್ಚರ.","ಅವಳು ಅರಸನಾದ ಅಹಷ್ವೇರೋಷನನ್ನು ಮದುವೆಯಾದಳು."]],
  ["ಪೇತ್ರ",["ಅವನು ಬೆಸ್ತನಾಗಿದ್ದನು.","ಅವನು ನೀರಿನ ಮೇಲೆ ನಡೆದನು."],["ಪ್ರಕಟನೆ ಪುಸ್ತಕವನ್ನು ಬರೆದನು.","ಪತ್ಮೊಸ್ ದ್ವೀಪದಲ್ಲಿ ಯೋಹಾನನು ಪ್ರಕಟನೆಯನ್ನು ಕಂಡನು."]],
  ["ಪೌಲ",["ಅವನಿಗೆ ಸೌಲ ಎಂಬ ಹೆಸರೂ ಇತ್ತು.","ಮೆಲೀತೆ ದ್ವೀಪದ ಬಳಿ ಅವನ ಹಡಗು ಒಡೆದುಹೋಯಿತು."],["ಯೇಸು ಮೊದಲು ಆರಿಸಿಕೊಂಡ ಹನ್ನೆರಡು ಶಿಷ್ಯರಲ್ಲಿ ಅವನು ಒಬ್ಬನು.","ಅವನು ಆನಂತರ ದಮಸ್ಕದ ಮಾರ್ಗದಲ್ಲಿ ಎದ್ದುಬಂದ ಯೇಸುವನ್ನು ಸಂಧಿಸಿದನು."]],
  ["ರೂತ",["ಅವಳು ಮೋವಾಬ್ ದೇಶದ ಸ್ತ್ರೀ.","ಬೋವಜನ ಹೊಲದಲ್ಲಿ ತೆನೆ ಆರಿಸಿದಳು."],["ಅವಳು ಅರಸನಾದ ದಾವೀದನ ತಾಯಿ.","ಅವಳು ದಾವೀದನ ಮುತ್ತಜ್ಜಿ."]],
  ["ಎಲೀಯ",["ಕಾಗೆಗಳು ಅವನಿಗೆ ರೊಟ್ಟಿಯನ್ನೂ ಮಾಂಸವನ್ನೂ ತಂದವು.","ಸುಂಟರಗಾಳಿಯಲ್ಲಿ ಪರಲೋಕಕ್ಕೆ ಏರಿಹೋದನು."],["ದೊಡ್ಡ ಮೀನು ಅವನನ್ನು ನುಂಗಿತು.","ಅದು ಯೋನ."]],
  ["ಯೋಸೇಫ",["ಅವನ ಅಣ್ಣಂದಿರು ಇಪ್ಪತ್ತು ಬೆಳ್ಳಿ ನಾಣ್ಯಗಳಿಗೆ ಅವನನ್ನು ಮಾರಿದರು.","ಫರೋಹನ ಕನಸುಗಳ ಅರ್ಥವನ್ನು ಹೇಳಿದನು."],["ಅವನು ಯಾಕೋಬನ ಚೊಚ್ಚಲ ಮಗ.","ರೂಬೇನನು ಚೊಚ್ಚಲ ಮಗ."]],
  ["ಅಬ್ರಹಾಮ",["ಕಸ್ದೀಯರ ಊರ್ ಪಟ್ಟಣದಿಂದ ಬಂದನು.","ಇಸಾಕನು ಹುಟ್ಟಿದಾಗ ಅವನಿಗೆ ನೂರು ವರ್ಷ."],["ಸಾರಳು ಅವನಿಗೆ ಹನ್ನೆರಡು ಗಂಡುಮಕ್ಕಳನ್ನು ಹೆತ್ತಳು.","ಸಾರಳು ಅವನಿಗೆ ಇಸಾಕನೆಂಬ ಒಬ್ಬನೇ ಮಗನನ್ನು ಹೆತ್ತಳು."]],
  ["ಯೇಸುವಿನ ತಾಯಿ ಮರಿಯ",["ಗಬ್ರಿಯೇಲ ದೂತನು ಅವಳ ಬಳಿಗೆ ಕಳುಹಿಸಲ್ಪಟ್ಟನು.","ಅವಳು ಯೇಸುವನ್ನು ಗೋದಲಿಯಲ್ಲಿ ಮಲಗಿಸಿದಳು."],["ಅವಳು ಯೆರಿಕೋವಿನಲ್ಲಿ ವಾಸಿಸುತ್ತಿದ್ದಳು.","ಗಬ್ರಿಯೇಲನು ನಜರೇತಿನಲ್ಲಿ ಅವಳ ಬಳಿಗೆ ಬಂದನು."]],
  ["ಜಕ್ಕಾಯ",["ಅವನು ಸುಂಕದವರಲ್ಲಿ ಮುಖ್ಯಸ್ಥನಾಗಿದ್ದನು.","ಅವನು ಕುಳ್ಳನಾಗಿದ್ದನು."],["ಅವನು ಎಣ್ಣೇಮರವನ್ನು ಹತ್ತಿದನು.","ಅವನು ಆಲದ ಮರವನ್ನು ಹತ್ತಿದನು."]],
  ["ಗಿದ್ಯೋನ",["ಉಣ್ಣೆಯ ಗುಜ್ಜಿನಿಂದ ಗುರುತನ್ನು ಕೇಳಿದನು.","ಮುನ್ನೂರು ಜನರೊಂದಿಗೆ ಮಿದ್ಯಾನ್ಯರ ವಿರುದ್ಧ ಹೋರಾಡಿದನು."],["ಇಸ್ರಾಯೇಲಿನ ಮೊದಲ ಅರಸನಾಗಲು ಒಪ್ಪಿದನು.","ಅವರನ್ನು ಆಳಲು ನಿರಾಕರಿಸಿದನು; ಸೌಲನು ಮೊದಲ ಅರಸನು."]],
  ["ಸೊಲೊಮೋನ",["ಜ್ಞಾನವುಳ್ಳ ಹೃದಯಕ್ಕಾಗಿ ದೇವರನ್ನು ಬೇಡಿದನು.","ಶೆಬದ ರಾಣಿ ಅವನನ್ನು ನೋಡಲು ಬಂದಳು."],["ಅವನು ಗೊಲ್ಯಾತನನ್ನು ಕೊಂದನು.","ಅವನ ತಂದೆ ದಾವೀದನು ಕೊಂದನು."]],
  ["ಯಾಕೋಬ",["ರಾಹೇಲಳಿಗಾಗಿ ಏಳು ವರ್ಷ ಸೇವೆ ಮಾಡಿದನು.","ದೇವರು ಅವನಿಗೆ ಇಸ್ರಾಯೇಲ್ ಎಂದು ಹೆಸರಿಟ್ಟನು."],["ತನ್ನ ಅವಳಿ ಏಸಾವನಿಗಿಂತ ಮೊದಲು ಹುಟ್ಟಿದನು.","ಏಸಾವನು ಮೊದಲು ಹೊರಬಂದನು."]],
  ["ತೋಮ",["ಅವನು ಹನ್ನೆರಡು ಮಂದಿಯಲ್ಲಿ ಒಬ್ಬನು.","ಅವನಿಗೆ ದಿದುಮ ಎಂಬ ಹೆಸರೂ ಇತ್ತು."],["ಯೇಸುವನ್ನು ಮೂರು ಸಾರಿ ಅಲ್ಲಗಳೆದನು.","ಅದು ಪೇತ್ರ."]],
  ["ಸ್ನಾನಿಕನಾದ ಯೋಹಾನ",["ಮಿಡತೆಗಳೂ ಕಾಡುಜೇನೂ ಅವನ ಆಹಾರವಾಗಿದ್ದವು.","ಅವನ ತಂದೆ ಜಕರೀಯ."],["ಯೇಸು ಅವನಿಗೆ ಬಾಪ್ತಿಸ್ಮ ಮಾಡಿಸಿದನು.","ಯೋಹಾನನು ಯೊರ್ದನಿನಲ್ಲಿ ಯೇಸುವಿಗೆ ಬಾಪ್ತಿಸ್ಮ ಮಾಡಿಸಿದನು."]],
  ["ಲಾಜರ",["ಮರಿಯ ಮತ್ತು ಮಾರ್ಥ ಅವನ ಸಹೋದರಿಯರು.","ನಾಲ್ಕು ದಿನ ಸಮಾಧಿಯಲ್ಲಿದ್ದನು."],["ಅವನು ಕಪೆರ್ನೌಮಿನಲ್ಲಿ ವಾಸಿಸುತ್ತಿದ್ದನು.","ಅವನು ಬೇಥಾನ್ಯದಲ್ಲಿ ವಾಸಿಸುತ್ತಿದ್ದನು."]],
  ["ಆದಾಮ",["ಎಲ್ಲಾ ಪಶುಗಳಿಗೂ ಪಕ್ಷಿಗಳಿಗೂ ಹೆಸರಿಟ್ಟನು.","ನೆಲದ ಧೂಳಿನಿಂದ ರೂಪಿಸಲ್ಪಟ್ಟನು."],["ಸಾವಿರ ವರ್ಷ ಬದುಕಿದನು.","ಅವನು ಒಂಬೈನೂರ ಮೂವತ್ತು ವರ್ಷ ಬದುಕಿದನು."]],
  ["ಮೆತೂಷೆಲಹ",["ಒಂಬೈನೂರ ಅರುವತ್ತೊಂಬತ್ತು ವರ್ಷ ಬದುಕಿದನು.","ಅವನು ನೋಹನ ಅಜ್ಜ."],["ಅವನು ನಾವೆಯನ್ನು ಕಟ್ಟಿದನು.","ಅವನ ಮೊಮ್ಮಗ ನೋಹನು ಅದನ್ನು ಕಟ್ಟಿದನು."]],
  ["ಹನ್ನ",["ಶೀಲೋವಿನಲ್ಲಿ ಮಗನಿಗಾಗಿ ಪ್ರಾರ್ಥಿಸಿದಳು.","ಸಮುವೇಲನನ್ನು ಕರ್ತನಿಗೆ ಒಪ್ಪಿಸಿದಳು."],["ಅವಳು ಅಬ್ರಹಾಮನ ಹೆಂಡತಿ.","ಅವಳು ಎಲ್ಕಾನನ ಹೆಂಡತಿ."]],
  ["ದೆಬೋರ",["ಇಸ್ರಾಯೇಲಿಗೆ ನ್ಯಾಯತೀರಿಸಿದ ಪ್ರವಾದಿನಿ.","ಖರ್ಜೂರದ ಮರದ ಕೆಳಗೆ ಕುಳಿತುಕೊಳ್ಳುತ್ತಿದ್ದಳು."],["ಗುಡಾರದ ಮೊಳೆಯಿಂದ ಸೀಸೆರನನ್ನು ಕೊಂದಳು.","ಯಾಯೇಲಳು ಕೊಂದಳು."]],
  ["ನಾಮಾನ",["ಅರಾಮ್ ಅರಸನ ಸೇನಾಪತಿಯಾಗಿದ್ದನು.","ಯೊರ್ದನಿನಲ್ಲಿ ಏಳು ಸಾರಿ ಮುಳುಗಿದನು."],["ಎಲೀಯನು ಅವನನ್ನು ಗುಣಪಡಿಸಿದನು.","ಯೊರ್ದನಿನಲ್ಲಿ ಸ್ನಾನಮಾಡು ಎಂದು ಎಲೀಷನು ಹೇಳಿ ಕಳುಹಿಸಿದನು."]],
  ["ನೆಹೆಮೀಯ",["ಅರಸನ ಪಾನದಾಯಕನಾಗಿದ್ದನು.","ಯೆರೂಸಲೇಮಿನ ಗೋಡೆಯನ್ನು ಮತ್ತೆ ಕಟ್ಟುವ ಕೆಲಸವನ್ನು ನಡೆಸಿದನು."],["ಅವನು ಐಗುಪ್ತದಲ್ಲಿ ಸೆರೆಯಾಳಾಗಿದ್ದನು.","ಅವನು ಪಾರಸಿಯ ಶೂಷನ್ ಅರಮನೆಯಲ್ಲಿ ಸೇವೆ ಮಾಡಿದನು."]],
  ["ಯೆಹೋಶುವ",["ಕಾನಾನನ್ನು ಸಂಚರಿಸಿ ನೋಡಲು ಕಳುಹಿಸಲ್ಪಟ್ಟವರಲ್ಲಿ ಒಬ್ಬನು.","ಯೆರಿಕೋವಿನ ಗೋಡೆ ಅವನ ಮುಂದೆ ಬಿದ್ದುಹೋಯಿತು."],["ಅವನು ಮೋಶೆಯ ಸಹೋದರ.","ಅವನು ಮೋಶೆಯ ಸೇವಕ; ಆರೋನನು ಸಹೋದರ."]],
  ["ಮತ್ತಾಯ",["ಅವನು ಸುಂಕದವನಾಗಿದ್ದನು.","ಯೇಸು ಕರೆದಾಗ ಸುಂಕದ ಕಟ್ಟೆಯಲ್ಲಿ ಕುಳಿತಿದ್ದನು."],["ಅವನು ಅಂದ್ರೆಯನ ಸಹೋದರ.","ಅಂದ್ರೆಯನು ಸೀಮೋನ ಪೇತ್ರನ ಸಹೋದರ."]],
  ["ಸ್ತೆಫನ",["ಸೇವೆಗಾಗಿ ಆರಿಸಲ್ಪಟ್ಟ ಏಳು ಮಂದಿಯಲ್ಲಿ ಒಬ್ಬನು.","ಸಾಯುವಾಗ ಆಕಾಶವು ತೆರೆದಿರುವುದನ್ನು ಕಂಡನು."],["ರೋಮಿನಲ್ಲಿ ಕಲ್ಲೆಸೆಯಲ್ಪಟ್ಟನು.","ಅವರು ಅವನನ್ನು ಯೆರೂಸಲೇಮ್ ಪಟ್ಟಣದ ಹೊರಗೆ ಹಾಕಿದರು."]],
  ["ಲುದ್ಯ",["ಧೂಮ್ರವರ್ಣದ ವಸ್ತ್ರಗಳನ್ನು ಮಾರುತ್ತಿದ್ದಳು.","ಅವಳು ಥುವತೈರ ಪಟ್ಟಣದವಳು."],["ಪೇತ್ರನು ಅವಳನ್ನು ಸತ್ತವರೊಳಗಿಂದ ಎಬ್ಬಿಸಿದನು.","ಅದು ತಬಿಥಾ; ಲುದ್ಯಳು ಬಾಪ್ತಿಸ್ಮ ಹೊಂದಿ ಪೌಲನಿಗೆ ಆತಿಥ್ಯ ನೀಡಿದಳು."]],
  ["ಎಲೀಷ",["ಎಲೀಯನ ಆತ್ಮದ ಎರಡು ಪಾಲನ್ನು ಕೇಳಿದನು.","ಕಬ್ಬಿಣದ ಕೊಡಲಿಯನ್ನು ನೀರಿನ ಮೇಲೆ ತೇಲುವಂತೆ ಮಾಡಿದನು."],["ಬೆಂಕಿಯ ರಥದಲ್ಲಿ ಪರಲೋಕಕ್ಕೆ ಏರಿಹೋದನು.","ಎಲೀಯನು ಹೋದನು; ಎಲೀಷನು ನೋಡುತ್ತಿದ್ದನು."]],
  ["ರಾಹಾಬ",["ಅವಳು ಯೆರಿಕೋವಿನಲ್ಲಿ ವಾಸಿಸುತ್ತಿದ್ದಳು.","ಇಬ್ಬರು ಗೂಢಚಾರರನ್ನು ತನ್ನ ಮಾಳಿಗೆಯ ಮೇಲೆ ಅಡಗಿಸಿಟ್ಟಳು."],["ತನ್ನ ಕಿಟಕಿಯಿಂದ ಬಿಳಿಯ ಬಟ್ಟೆಯನ್ನು ತೂಗಹಾಕಿದಳು.","ಅವಳು ಕಿಟಕಿಗೆ ಕೆಂಪು ನೂಲಿನ ದಾರವನ್ನು ಕಟ್ಟಿದಳು."]],
  ["ಅರಸನಾದ ಸೌಲ",["ಅವನು ಬೆನ್ಯಾಮೀನ್ ಕುಲದವನು.","ಜನರೆಲ್ಲರಿಗಿಂತ ಎತ್ತರವಾಗಿದ್ದನು."],["ನಾತಾನನು ಅವನನ್ನು ಅರಸನಾಗಿ ಅಭಿಷೇಕಿಸಿದನು.","ಸಮುವೇಲನು ಅಭಿಷೇಕಿಸಿದನು."]],
  ["ನಿಕೊದೇಮ",["ರಾತ್ರಿಯಲ್ಲಿ ಯೇಸುವಿನ ಬಳಿಗೆ ಬಂದನು.","ಅವನು ಫರಿಸಾಯನಾಗಿದ್ದನು."],["ಅವನು ಗಲಿಲಾಯದ ಬೆಸ್ತನಾಗಿದ್ದನು.","ಅವನು ಯೆಹೂದ್ಯರ ಅಧಿಕಾರಿಯಾಗಿದ್ದನು."]],
  ["ಮಾರ್ಥ",["ಅವಳು ಲಾಜರನ ಸಹೋದರಿ.","ಬಹಳ ಸೇವೆಯ ಕೆಲಸದಲ್ಲಿ ಚಿಂತೆಗೊಂಡಿದ್ದಳು."],["ಯೇಸುವಿನ ಪಾದಗಳಿಗೆ ತೈಲವನ್ನು ಹಚ್ಚಿದಳು.","ಅವಳ ಸಹೋದರಿ ಮರಿಯಳು ಹಚ್ಚಿದಳು."]],
  ["ಬಾರ್ನಬ",["ಸೌಲನೊಂದಿಗೆ ಕಳುಹಿಸಲ್ಪಟ್ಟನು.","ಅವನು ಕುಪ್ರ ದ್ವೀಪದವನು."],["ರೋಮಾಪುರದವರಿಗೆ ಪತ್ರವನ್ನು ಬರೆದನು.","ಪೌಲನು ಅದನ್ನು ಬರೆದನು."]],
  ["ತಿಮೊಥೆಯ",["ಅವನ ತಾಯಿ ಯೂನೀಕೆ.","ಅವನ ಅಜ್ಜಿ ಲೋವಿ."],["ಅವನು ಹನ್ನೆರಡು ಅಪೊಸ್ತಲರಲ್ಲಿ ಒಬ್ಬನು.","ಅವನು ನಂಬಿಕೆಯಲ್ಲಿ ಪೌಲನ ಮಗ; ಆನಂತರ ಕರೆಯಲ್ಪಟ್ಟನು."]],
  ["ಯೋಬ",["ಊಚ್ ದೇಶದಲ್ಲಿ ವಾಸಿಸುತ್ತಿದ್ದನು.","ಅವನಿಗೆ ಏಳು ಗಂಡುಮಕ್ಕಳೂ ಮೂರು ಹೆಣ್ಣುಮಕ್ಕಳೂ ಇದ್ದರು."],["ಎಲ್ಲವನ್ನೂ ಕಳೆದುಕೊಂಡಾಗ ದೇವರನ್ನು ದೂಷಿಸಿದನು.","ಇದೆಲ್ಲದರಲ್ಲಿ ಯೋಬನು ಪಾಪಮಾಡಲಿಲ್ಲ."]],
  ["ಕಾಯಿನ",["ಅವನು ಭೂಮಿಯನ್ನು ವ್ಯವಸಾಯ ಮಾಡುವವನು.","ಆದಾಮ ಹವ್ವರ ಚೊಚ್ಚಲ ಮಗ."],["ಅವನ ತಮ್ಮ ಹೇಬೆಲನು ಅವನನ್ನು ಕೊಂದನು.","ಕಾಯಿನನು ಹೇಬೆಲನನ್ನು ಕೊಂದನು."]],
  ["ಹವ್ವ",["ಆದಾಮನಿಂದ ತೆಗೆದ ಪಕ್ಕೆಲುಬಿನಿಂದ ಅವಳು ಉಂಟುಮಾಡಲ್ಪಟ್ಟಳು.","ತೋಟದಲ್ಲಿ ಸರ್ಪವು ಅವಳೊಂದಿಗೆ ಮಾತನಾಡಿತು."],["ಅವಳು ಸೇಬಿನ ಹಣ್ಣನ್ನು ತಿಂದಳೆಂದು ಸತ್ಯವೇದ ಹೇಳುತ್ತದೆ.","ಸತ್ಯವೇದ \"ಆ ಮರದ ಹಣ್ಣು\" ಎಂದು ಮಾತ್ರ ಹೇಳುತ್ತದೆ."]],
  ["ಸಾರ",["ತನಗೆ ಮಗನು ಹುಟ್ಟುವನೆಂದು ಕೇಳಿ ಅವಳು ನಕ್ಕಳು.","ಅವಳ ಹೆಸರು ಹಿಂದೆ ಸಾರಯ ಎಂದಿತ್ತು."],["ಇಸಾಕನು ಹುಟ್ಟುವ ಮೊದಲೇ ಅವಳು ಸತ್ತಳು.","ಅವಳು ಇಸಾಕನನ್ನು ಹೆತ್ತು, ಅನೇಕ ವರುಷಗಳ ನಂತರ ಹೆಬ್ರೋನಿನಲ್ಲಿ ಸತ್ತಳು."]],
  ["ಲೋಟ",["ಅವನು ಅಬ್ರಹಾಮನ ತಮ್ಮನ ಮಗನು.","ಅವನು ಯೊರ್ದನಿನ ಬಯಲನ್ನು ಆರಿಸಿಕೊಂಡನು."],["ಅವನ ಹೆಂಡತಿ ಬಂಗಾರದ ಕಂಬವಾದಳು.","ಅವಳು ಉಪ್ಪಿನ ಕಂಬವಾದಳು."]],
  ["ಇಸಾಕ",["ಅವನ ಹೆಸರಿಗೆ ನಗು ಎಂಬ ಅರ್ಥವಿದೆ.","ಅವನು ರೆಬೆಕ್ಕಳನ್ನು ಮದುವೆಯಾದನು."],["ಅವನಿಗೆ ಹನ್ನೆರಡು ಮಂದಿ ಗಂಡುಮಕ್ಕಳಿದ್ದರು.","ಅವನಿಗೆ ಏಸಾವ ಯಾಕೋಬರೆಂಬ ಇಬ್ಬರು ಗಂಡುಮಕ್ಕಳಿದ್ದರು."]],
  ["ಏಸಾವ",["ಅವನು ಬೇಟೆಯಲ್ಲಿ ನಿಪುಣನಾಗಿದ್ದನು.","ಅವನು ಗಂಜಿಗಾಗಿ ತನ್ನ ಚೊಚ್ಚಲತನವನ್ನು ಮಾರಿದನು."],["ಅವನು ಅವಳಿಗಳಲ್ಲಿ ಕಿರಿಯವನು.","ಅವನು ಮೊದಲು ಹೊರಬಂದನು; ಯಾಕೋಬನು ಅವನ ಹಿಮ್ಮಡಿಯನ್ನು ಹಿಡಿದಿದ್ದನು."]],
  ["ರೆಬೆಕ್ಕ",["ಅಬ್ರಹಾಮನ ಸೇವಕನ ಒಂಟೆಗಳಿಗೆ ಅವಳು ನೀರು ಕೊಟ್ಟಳು.","ಅವಳು ಲಾಬಾನನ ತಂಗಿ."],["ಅವಳು ಯಾಕೋಬನಿಗಿಂತ ಏಸಾವನನ್ನು ಹೆಚ್ಚಾಗಿ ಪ್ರೀತಿಸಿದಳು.","ರೆಬೆಕ್ಕಳು ಯಾಕೋಬನನ್ನು ಪ್ರೀತಿಸಿದಳು; ಇಸಾಕನು ಏಸಾವನನ್ನು ಪ್ರೀತಿಸಿದನು."]],
  ["ಲಾಬಾನ",["ರಾಹೇಲಳ ಬದಲಿಗೆ ಲೇಯಳನ್ನು ಯಾಕೋಬನಿಗೆ ಕೊಟ್ಟನು.","ಯಾಕೋಬನ ಸಂಬಳವನ್ನು ಹತ್ತು ಸಾರಿ ಬದಲಾಯಿಸಿದನು."],["ಅವನು ಯಾಕೋಬನ ಅಣ್ಣ.","ಅವನು ಯಾಕೋಬನ ತಾಯಿಯ ಅಣ್ಣ, ಅಂದರೆ ಸೋದರಮಾವ."]],
  ["ರಾಹೇಲ",["ಅವಳಿಗಾಗಿ ಯಾಕೋಬನು ಏಳು ವರುಷ ಸೇವೆಮಾಡಿದನು.","ಅವಳು ಯೋಸೇಫನ ತಾಯಿ."],["ಅವಳನ್ನು ಹೆಬ್ರೋನಿನಲ್ಲಿ ಅಬ್ರಹಾಮನ ಬಳಿ ಹೂಣಿಟ್ಟರು.","ಅವಳನ್ನು ಬೇತ್ಲೆಹೇಮಿಗೆ ಹೋಗುವ ದಾರಿಯಲ್ಲಿ ಹೂಣಿಟ್ಟರು."]],
  ["ಯೆಹೂದ",["ಬೆನ್ಯಾಮೀನನ ಬದಲಿಗೆ ತಾನೇ ದಾಸನಾಗಿರುವೆನೆಂದು ಹೇಳಿದನು.","ಯೋಸೇಫನನ್ನು ಕೊಲ್ಲುವ ಬದಲು ಮಾರಿಬಿಡೋಣ ಎಂದನು."],["ಅವನು ಯಾಕೋಬನ ಕಡೇ ಮಗನು.","ಬೆನ್ಯಾಮೀನನು ಕಡೇ ಮಗನು; ಯೆಹೂದನು ಲೇಯಳ ನಾಲ್ಕನೆಯ ಮಗನು."]],
  ["ಮೆಲ್ಕೀಚೆದೇಕ",["ಅವನು ಸಾಲೇಮಿನ ಅರಸನು.","ಅವನು ಅಬ್ರಾಮನಿಗೆ ರೊಟ್ಟಿಯನ್ನೂ ದ್ರಾಕ್ಷಾರಸವನ್ನೂ ತಂದನು."],["ಅಬ್ರಾಮನು ತನ್ನಲ್ಲಿದ್ದ ಎಲ್ಲದರಲ್ಲಿ ಅರ್ಧವನ್ನು ಅವನಿಗೆ ಕೊಟ್ಟನು.","ಅಬ್ರಾಮನು ಎಲ್ಲದರಲ್ಲಿ ಹತ್ತನೆಯ ಒಂದು ಪಾಲನ್ನು ಅವನಿಗೆ ಕೊಟ್ಟನು."]],
  ["ಆರೋನ",["ಅವನು ಮೋಶೆಗಿಂತ ದೊಡ್ಡವನು.","ಅವನು ಬಂಗಾರದ ಕರುವನ್ನು ಮಾಡಿದನು."],["ಅವನು ಯೆಹೂದ ಗೋತ್ರದವನು.","ಅವನು ಲೇವಿಯನು."]],
  ["ಮಿರ್ಯಾಮ",["ಅವಳು ದಮ್ಮಡಿಯನ್ನು ಹಿಡಿದು ಸ್ತ್ರೀಯರನ್ನು ಹಾಡಿನಲ್ಲಿ ನಡೆಸಿದಳು.","ಅವಳನ್ನು ಪ್ರವಾದಿನಿ ಎಂದು ಕರೆಯಲಾಗಿದೆ."],["ಅವಳು ಫರೋಹನ ಮಗಳು.","ಅವಳು ಆರೋನ ಮೋಶೆಯರ ಅಕ್ಕ."]],
  ["ಇತ್ರೋ",["ಅವನು ಮಿದ್ಯಾನಿನ ಯಾಜಕನು.","ಜನರಿಗೆ ನ್ಯಾಯತೀರಿಸಲು ಅಧಿಕಾರಿಗಳನ್ನು ನೇಮಿಸಬೇಕೆಂದು ಮೋಶೆಗೆ ಸಲಹೆಕೊಟ್ಟನು."],["ಅವನು ಫರೋಹನ ತಂದೆ.","ಅವನು ಮೋಶೆಯ ಮಾವ."]],
  ["ಫರೋಹ",["ಹುಲ್ಲಿಲ್ಲದೆ ಇಟ್ಟಿಗೆ ಮಾಡುವಂತೆ ಇಬ್ರಿಯರನ್ನು ಒತ್ತಾಯಿಸಿದನು.","ಅವನ ಹೃದಯವು ಕಠಿಣವಾಯಿತು."],["ಮೊದಲನೆಯ ಬಾಧೆಯ ನಂತರವೇ ಅವನು ಜನರನ್ನು ಹೋಗಗೊಟ್ಟನು.","ಹತ್ತನೆಯ ಬಾಧೆಯ ನಂತರವೇ ಅವರನ್ನು ಹೋಗಗೊಟ್ಟನು."]],
  ["ಚಿಪ್ಪೋರ",["ಅವಳು ಮಿದ್ಯಾನಿನ ಯಾಜಕನ ಮಗಳು.","ಅವಳು ಮೋಶೆಯ ಹೆಂಡತಿ."],["ಅವಳಿಗೆ ಹನ್ನೆರಡು ಮಂದಿ ಗಂಡುಮಕ್ಕಳಿದ್ದರು.","ವಿಮೋಚನಕಾಂಡದಲ್ಲಿ ಹೇಳಿರುವ ಅವಳ ಮಕ್ಕಳು ಗೇರ್ಷೋಮ್ ಮತ್ತು ಎಲೀಯೆಜೆರ್."]],
  ["ಬೆಚಲೇಲ",["ಎಲ್ಲಾ ಕೆಲಸಗಾರಿಕೆಯಲ್ಲಿ ಅವನು ದೇವರ ಆತ್ಮದಿಂದ ತುಂಬಲ್ಪಟ್ಟನು.","ಅವನು ಜಾಲೀಮರದ ಮಂಜೂಷವನ್ನು ಮಾಡಿದನು."],["ಅವನು ಲೇವಿ ಗೋತ್ರದವನು.","ಅವನು ಯೆಹೂದ ಗೋತ್ರದವನು."]],
  ["ಅರಣ್ಯದಲ್ಲಿ ಇಸ್ರಾಯೇಲ್ಯರು",["ಅವರು ಮನ್ನವನ್ನು ತಿಂದರು.","ಹೋರೇಬಿನಲ್ಲಿ ಬಂಡೆಯಿಂದ ಬಂದ ನೀರನ್ನು ಕುಡಿದರು."],["ಅವರು ತೆಪ್ಪಗಳ ಮೇಲೆ ಕೆಂಪು ಸಮುದ್ರವನ್ನು ದಾಟಿದರು.","ಅವರು ಒಣನೆಲದ ಮೇಲೆ ನಡೆದು ದಾಟಿದರು."]],
  ["ಹೂರ",["ಆರೋನನೊಂದಿಗೆ ಮೋಶೆಯ ಕೈಗಳನ್ನು ಎತ್ತಿಹಿಡಿದನು.","ಮೋಶೆ ಬೆಟ್ಟವನ್ನು ಹತ್ತಿದಾಗ ಆರೋನನೊಂದಿಗೆ ಜನರ ಮೇಲ್ವಿಚಾರಣೆ ಅವನಿಗಿತ್ತು."],["ಅವನು ಬಂಗಾರದ ಕರುವನ್ನು ಮಾಡಿದನು.","ಆರೋನನು ಆ ಕರುವನ್ನು ಮಾಡಿದನು."]],
  ["ಕೂಸಾದ ಮೋಶೆ",["ಅವನನ್ನು ಆಪಿನ ಪೆಟ್ಟಿಗೆಯಲ್ಲಿ ಇಟ್ಟರು.","ಫರೋಹನ ಮಗಳು ಅವನನ್ನು ಕಂಡುಕೊಂಡಳು."],["ಅವನನ್ನು ಮೂರು ವರುಷ ಗುಹೆಯಲ್ಲಿ ಅಡಗಿಸಿಟ್ಟರು.","ಅವನ ತಾಯಿ ಅವನನ್ನು ಮೂರು ತಿಂಗಳು ಅಡಗಿಸಿಟ್ಟಳು."]],
  ["ಸೀನಾಯಿಯಲ್ಲಿ ಮೋಶೆ",["ಅವನು ನಾಲ್ವತ್ತು ದಿನ ನಾಲ್ವತ್ತು ರಾತ್ರಿ ಬೆಟ್ಟದ ಮೇಲಿದ್ದನು.","ಕೆಳಗೆ ಇಳಿದು ಬಂದಾಗ ಅವನ ಮುಖವು ಪ್ರಕಾಶಿಸುತ್ತಿತ್ತು."],["ಅವನು ಕರ್ಮೆಲ್ ಬೆಟ್ಟದ ಮೇಲೆ ಧರ್ಮಶಾಸ್ತ್ರವನ್ನು ಹೊಂದಿದನು.","ಅದು ಸೀನಾಯಿ ಬೆಟ್ಟ."]],
  ["ಯೆಹೋಶುವ",["ಅವನು ನೂನನ ಮಗನು.","ಸೂರ್ಯನೇ, ಗಿಬ್ಯೋನಿನ ಮೇಲೆ ನಿಲ್ಲು ಎಂದು ಹೇಳಿದನು."],["ಕೆಟ್ಟ ವರ್ತಮಾನ ತಂದ ಹತ್ತು ಮಂದಿ ಗೂಢಚಾರರಲ್ಲಿ ಅವನೂ ಒಬ್ಬನು.","ಅವನೂ ಕಾಲೇಬನೂ ಒಳ್ಳೇ ವರ್ತಮಾನವನ್ನು ತಂದರು."]],
  ["ಯೆರಿಕೋವಿನ ಗೂಢಚಾರರು",["ಅವರು ರಾಹಾಬಳ ಮನೆಯಲ್ಲಿ ಇಳಿದುಕೊಂಡರು.","ಅವರು ಮಾಳಿಗೆಯ ಮೇಲೆ ನಾರಿನ ದಂಟುಗಳ ಕೆಳಗೆ ಅಡಗಿಕೊಂಡರು."],["ಅವರು ಹನ್ನೆರಡು ಮಂದಿ ಇದ್ದರು.","ಯೆಹೋಶುವನು ಇಬ್ಬರನ್ನು ಕಳುಹಿಸಿದನು."]],
  ["ಯೆರಿಕೋವಿನ ಗೋಡೆಗಳು",["ಜನರು ಏಳು ದಿನ ಪಟ್ಟಣವನ್ನು ಸುತ್ತಿದರು.","ಯಾಜಕರು ಟಗರಿನ ಕೊಂಬುಗಳ ತುತೂರಿಗಳನ್ನು ಊದಿದರು."],["ಯೆಹೋಶುವನು ತನ್ನ ಕೋಲಿನಿಂದ ಹೊಡೆದಾಗ ಅವು ಬಿದ್ದವು.","ಜನರು ಆರ್ಭಟಿಸಿದಾಗ ಅವು ಬಿದ್ದವು."]],
  ["ಆಕಾನ",["ಅವನು ಒಂದು ಶ್ರೇಷ್ಠವಾದ ಬಾಬೆಲಿನ ವಸ್ತ್ರವನ್ನು ತಕ್ಕೊಂಡನು.","ತಾನು ತಕ್ಕೊಂಡದ್ದನ್ನು ತನ್ನ ಗುಡಾರದೊಳಗೆ ಭೂಮಿಯಲ್ಲಿ ಬಚ್ಚಿಟ್ಟನು."],["ಅವನಿಗೆ ಕ್ಷಮೆ ದೊರೆತು ಕೊಳ್ಳೆಯಲ್ಲಿ ಪಾಲು ಸಿಕ್ಕಿತು.","ಆಕೋರ್ ತಗ್ಗಿನಲ್ಲಿ ಅವನನ್ನು ಕಲ್ಲೆಸೆದು ಕೊಂದರು."]],
  ["ಗಿಬ್ಯೋನ್ಯರು",["ಅವರು ಹಳೇ ಕೆರಗಳನ್ನೂ ಹಳೇ ಬಟ್ಟೆಗಳನ್ನೂ ಹಾಕಿಕೊಂಡು ಬಂದರು.","ಅವರು ಕಟ್ಟಿಗೆ ಒಡೆಯುವವರೂ ನೀರು ತರುವವರೂ ಆದರು."],["ಒಡಂಬಡಿಕೆ ಮಾಡುವ ಮೊದಲೇ ಯೆಹೋಶುವನು ಅವರ ಮೋಸವನ್ನು ಕಂಡುಹಿಡಿದನು.","ಮೊದಲು ಅವರೊಂದಿಗೆ ಸಮಾಧಾನ ಮಾಡಿಕೊಂಡನು; ಮೂರು ದಿನಗಳ ನಂತರ ಸತ್ಯ ತಿಳಿಯಿತು."]],
  ["ಕಾಲೇಬ",["ಹೆಬ್ರೋನನ್ನು ಕೇಳಿದಾಗ ಅವನಿಗೆ ಎಂಭತ್ತೈದು ವರುಷವಾಗಿತ್ತು.","ಅವನು ತನ್ನ ಮಗಳಾದ ಅಕ್ಸಳನ್ನು ಒತ್ನೀಯೇಲನಿಗೆ ಕೊಟ್ಟನು."],["ಅವನು ಎಫ್ರಾಯೀಮ್ ಗೋತ್ರದವನು.","ಅವನು ಯೆಹೂದ ಗೋತ್ರದವನು."]],
  ["ಯೊರ್ದನನ್ನು ದಾಟಿದ್ದು",["ಯಾಜಕರ ಕಾಲುಗಳು ನೀರನ್ನು ಮುಟ್ಟಿದಾಗ ನೀರು ನಿಂತುಕೊಂಡಿತು.","ನದಿಯೊಳಗಿಂದ ಹನ್ನೆರಡು ಕಲ್ಲುಗಳನ್ನು ತೆಗೆದರು."],["ನದಿ ಕಡಿಮೆಯಾಗಿದ್ದ ಬೇಸಿಗೆಯಲ್ಲಿ ಇದು ನಡೆಯಿತು.","ಸುಗ್ಗಿಯ ಕಾಲದಲ್ಲಿ ಯೊರ್ದನ್ ನದಿ ದಡಗಳನ್ನು ಮೀರಿ ಹರಿಯುತ್ತಿತ್ತು."]],
  ["ಆಶ್ರಯ ಪಟ್ಟಣಗಳು",["ತಿಳಿಯದೆ ಮನುಷ್ಯನನ್ನು ಕೊಂದವನಿಗಾಗಿ ಅವು ಇದ್ದವು.","ಹೆಬ್ರೋನ್ ಅವುಗಳಲ್ಲಿ ಒಂದು."],["ಪ್ರತಿ ಗೋತ್ರಕ್ಕೆ ಒಂದರಂತೆ ಹನ್ನೆರಡು ಪಟ್ಟಣಗಳಿದ್ದವು.","ಆರು ಆಶ್ರಯ ಪಟ್ಟಣಗಳಿದ್ದವು."]],
  ["ಯೆಹೋಶುವನ ಕಡೇ ಮಾತುಗಳು",["ನಾನೂ ನನ್ನ ಮನೆಯವರೂ ಯೆಹೋವನನ್ನೇ ಸೇವಿಸುವೆವು ಎಂದು ಹೇಳಿದನು.","ಸಾಕ್ಷಿಗಾಗಿ ಒಂದು ಏಲಾ ಮರದ ಕೆಳಗೆ ದೊಡ್ಡ ಕಲ್ಲನ್ನು ನಿಲ್ಲಿಸಿದನು."],["ಅವನು ಎಪ್ಪತ್ತು ವರುಷದವನಾಗಿ ಸತ್ತನು.","ಅವನು ನೂರಹತ್ತು ವರುಷದವನಾಗಿ ಸತ್ತನು."]],
  ["ಆಯಿ ಪಟ್ಟಣದ ಯುದ್ಧ",["ಆಕಾನನ ಪಾಪದ ನಿಮಿತ್ತ ಇಸ್ರಾಯೇಲ್ಯರು ಮೊದಲ ಯುದ್ಧದಲ್ಲಿ ಸೋತರು.","ಯೆಹೋಶುವನು ಪಟ್ಟಣದ ಹಿಂದೆ ಹೊಂಚುಗಾರರನ್ನು ಇಟ್ಟನು."],["ಮೊದಲ ಸಾರಿ ಇಡೀ ಸೈನ್ಯವನ್ನು ಕಳುಹಿಸಿದರು.","ಸುಮಾರು ಮೂರು ಸಾವಿರ ಜನರನ್ನು ಮಾತ್ರ ಕಳುಹಿಸಿದರು."]],
  ["ಏಹೂದ",["ಅವನು ಎಡಚನಾಗಿದ್ದನು.","ಅವನು ಎರಡು ಬಾಯಿಯ ಕತ್ತಿಯನ್ನು ಮಾಡಿಕೊಂಡನು."],["ಅವನು ಕವಣೆಯ ಕಲ್ಲಿನಿಂದ ಅರಸನಾದ ಎಗ್ಲೋನನನ್ನು ಕೊಂದನು.","ಅವನು ಎಗ್ಲೋನನ ಹೊಟ್ಟೆಯೊಳಗೆ ಕತ್ತಿಯನ್ನು ತಿವಿದನು."]],
  ["ಯಾಯೇಲ",["ಅವಳು ಸೀಸೆರನಿಗೆ ಹಾಲನ್ನು ಕುಡಿಯಕೊಟ್ಟಳು.","ಅವಳು ಕೇನ್ಯನಾದ ಹೆಬೆರನ ಹೆಂಡತಿ."],["ಅವಳು ಕತ್ತಿಯಿಂದ ಸೀಸೆರನನ್ನು ಕೊಂದಳು.","ಅವಳು ಗುಡಾರದ ಗೂಟವನ್ನು ಅವನ ಕಣತಲೆಯೊಳಗೆ ಹೊಡೆದಳು."]],
  ["ಬಾರಾಕ",["ದೆಬೋರಳು ಬಾರದಿದ್ದರೆ ತಾನು ಯುದ್ಧಕ್ಕೆ ಹೋಗುವದಿಲ್ಲವೆಂದನು.","ಅವನು ಹತ್ತು ಸಾವಿರ ಜನರನ್ನು ತಾಬೋರ್ ಬೆಟ್ಟದಿಂದ ಇಳಿಸಿ ನಡೆಸಿದನು."],["ಅವನೇ ಸೀಸೆರನನ್ನು ಕೊಂದನು.","ಯಾಯೇಲಳೆಂಬ ಸ್ತ್ರೀ ಸೀಸೆರನನ್ನು ಕೊಂದಳು."]],
  ["ಯೆಫ್ತಾಹ",["ಅವನು ಗಿಲ್ಯಾದಿನ ಪರಾಕ್ರಮಶಾಲಿ.","ಯುದ್ಧಕ್ಕೆ ಮೊದಲು ಅವನು ಯೆಹೋವನಿಗೆ ಹರಕೆ ಮಾಡಿದನು."],["ಅವನಿಗೆ ಅನೇಕ ಗಂಡು ಹೆಣ್ಣು ಮಕ್ಕಳಿದ್ದರು.","ಅವನ ಮಗಳು ಅವನಿಗೆ ಒಬ್ಬಳೇ ಮಗಳು."]],
  ["ಸಂಸೋನನ ತಂದೆತಾಯಿ",["ಅವನ ತಾಯಿಗೆ ಮಗನು ಹುಟ್ಟುವನೆಂದು ದೂತನು ಹೇಳಿದನು.","ಅವನ ತಂದೆಯ ಹೆಸರು ಮಾನೋಹ."],["ಅವರು ಬೇತ್ಲೆಹೇಮಿನಲ್ಲಿ ವಾಸವಾಗಿದ್ದರು.","ಅವರು ದಾನ್ ಗೋತ್ರದವರು, ಚೊರ್ಗಾ ಊರಿನವರು."]],
  ["ಅಬೀಮೆಲೆಕ",["ಅವನು ಗಿದ್ಯೋನನ ಮಗನು.","ತನ್ನ ಎಪ್ಪತ್ತು ಮಂದಿ ಸಹೋದರರನ್ನು ಒಂದೇ ಕಲ್ಲಿನ ಮೇಲೆ ಕೊಂದನು."],["ಇಸ್ರಾಯೇಲಿಗೆಲ್ಲಾ ಅರಸನಾಗಿದ್ದು ಮುದುಕನಾಗಿ ಸತ್ತನು.","ಒಬ್ಬ ಸ್ತ್ರೀ ಬೀಸುವ ಕಲ್ಲಿನ ತುಂಡನ್ನು ಅವನ ತಲೆಯ ಮೇಲೆ ಹಾಕಿದಳು."]],
  ["ಒತ್ನೀಯೇಲ",["ಅವನು ಇಸ್ರಾಯೇಲಿನ ಮೊದಲ ನ್ಯಾಯಾಧಿಪತಿ.","ಅವನು ಕಾಲೇಬನ ತಮ್ಮನ ಮಗನು."],["ಅವನು ಎಂಭತ್ತು ವರುಷ ಇಸ್ರಾಯೇಲಿಗೆ ನ್ಯಾಯತೀರಿಸಿದನು.","ದೇಶಕ್ಕೆ ನಾಲ್ವತ್ತು ವರುಷ ವಿಶ್ರಾಂತಿ ಇತ್ತು."]],
  ["ಗಿದ್ಯೋನನ ಉಣ್ಣೆ",["ಮೊದಲು ಉಣ್ಣೆ ಒದ್ದೆಯಾಗಿ ನೆಲ ಒಣಗಿತ್ತು.","ಆಮೇಲೆ ಉಣ್ಣೆ ಒಣಗಿ ನೆಲ ಒದ್ದೆಯಾಗಿತ್ತು."],["ಅವನು ಅದರಿಂದ ಒಂದು ಪೀಪಾಯಿ ಎಣ್ಣೆಯನ್ನು ಹಿಂಡಿದನು.","ಅವನು ಅದರಿಂದ ಒಂದು ಬಟ್ಟಲು ತುಂಬ ನೀರನ್ನು ಹಿಂಡಿದನು."]],
  ["ದೆಲೀಲ",["ಅವಳು ಸೋರೇಕ್ ತಗ್ಗಿನಲ್ಲಿ ವಾಸವಾಗಿದ್ದಳು.","ಸಂಸೋನನು ಹೇಳುವ ಮೊದಲು ಮೂರು ಸಾರಿ ಅವನ ಬಲದ ಗುಟ್ಟನ್ನು ಕೇಳಿದಳು."],["ಅವಳೇ ಸಂಸೋನನ ಕೂದಲನ್ನು ಕತ್ತರಿಸಿದಳು.","ಏಳು ಜಡೆಗಳನ್ನು ಬೋಳಿಸಲು ಒಬ್ಬ ಮನುಷ್ಯನನ್ನು ಕರೆಸಿದಳು."]],
  ["ಶಮ್ಗರ",["ಅವನು ಅನಾತನ ಮಗನು.","ಅವನು ಇಸ್ರಾಯೇಲ್ಯರನ್ನು ರಕ್ಷಿಸಿದನು."],["ಕತ್ತೆಯ ದವಡೆಯ ಎಲುಬಿನಿಂದ ಫಿಲಿಷ್ಟಿಯರನ್ನು ಕೊಂದನು.","ಅವನು ಎತ್ತಿನ ಮುಳುಗೋಲನ್ನು ಉಪಯೋಗಿಸಿದನು; ದವಡೆ ಎಲುಬು ಸಂಸೋನನದು."]],
  ["ನವೊಮಿ",["ಅವಳ ಗಂಡನು ಎಲೀಮೆಲೆಕನು.","ತನ್ನನ್ನು ಮಾರಾ ಎಂದು ಕರೆಯಿರಿ ಎಂದಳು."],["ಅವಳು ತನ್ನ ಇಬ್ಬರು ಹೆಣ್ಣುಮಕ್ಕಳೊಂದಿಗೆ ಮೋವಾಬಿಗೆ ಹೋದಳು.","ಅವಳು ಗಂಡನೊಂದಿಗೂ ಇಬ್ಬರು ಗಂಡುಮಕ್ಕಳೊಂದಿಗೂ ಹೋದಳು."]],
  ["ಬೋವಜ",["ಅವನು ದೊಡ್ಡ ಐಶ್ವರ್ಯವಂತನು.","ರೂತಳಿಗಾಗಿ ಬೇಕೆಂದೇ ಹಿಡಿಗಳನ್ನು ಬೀಳಿಸಬೇಕೆಂದು ಕೊಯ್ಯುವವರಿಗೆ ಹೇಳಿದನು."],["ಅವನು ನವೊಮಿಯ ಮಗನು.","ಅವನು ಅವಳ ಗಂಡನಾದ ಎಲೀಮೆಲೆಕನ ಬಂಧು."]],
  ["ಒರ್ಫಾ",["ಅವಳು ಮೋವಾಬ್ ದೇಶದವಳು.","ಅವಳು ನವೊಮಿಯನ್ನು ಮುದ್ದಿಟ್ಟು ಬೀಳ್ಕೊಂಡಳು."],["ಅವಳು ನವೊಮಿಯೊಂದಿಗೆ ಬೇತ್ಲೆಹೇಮಿಗೆ ಹೋದಳು.","ಅವಳು ತನ್ನ ಜನರ ಬಳಿಗೆ ಹಿಂತಿರುಗಿದಳು."]],
  ["ರೂತಳ ಪ್ರಮಾಣ",["ನಿನ್ನ ಜನರೇ ನನ್ನ ಜನರು ಎಂದಳು.","ನೀನು ಎಲ್ಲಿ ಸಾಯುತ್ತೀಯೋ ಅಲ್ಲೇ ನಾನೂ ಸಾಯುವೆನು ಎಂದಳು."],["ಈ ಮಾತುಗಳನ್ನು ಅವಳು ಬೋವಜನಿಗೆ ಹೇಳಿದಳು.","ಅವಳು ಇವುಗಳನ್ನು ನವೊಮಿಗೆ ಹೇಳಿದಳು."]],
  ["ಸಮೀಪ ಬಂಧು",["ರೂತಳನ್ನು ಮದುವೆಯಾಗಬೇಕೆಂದು ಕೇಳಿ ಹೊಲವನ್ನು ವಿಮೋಚಿಸಲು ಒಪ್ಪಲಿಲ್ಲ.","ತನ್ನ ಕೆರವನ್ನು ತೆಗೆದು ಬೋವಜನಿಗೆ ಕೊಟ್ಟನು."],["ಅವನ ಹೆಸರು ಓಬೇದ.","ಅವನ ಹೆಸರು ಹೇಳಲ್ಪಟ್ಟಿಲ್ಲ; ಓಬೇದನು ರೂತಳ ಮಗನು."]],
  ["ಕಣದಲ್ಲಿ ರೂತ",["ಅವಳು ಬೋವಜನ ಕಾಲುಗಳ ಬಳಿಯಲ್ಲಿ ಮಲಗಿಕೊಂಡಳು.","ಬೋವಜನು ಅವಳಿಗೆ ಆರು ಅಳತೆ ಜವೆಗೋಧಿಯನ್ನು ಕೊಟ್ಟನು."],["ಸಂಬಳ ಕೇಳಲು ಅವಳು ಮಧ್ಯಾಹ್ನದಲ್ಲಿ ಅಲ್ಲಿಗೆ ಹೋದಳು.","ನವೊಮಿ ಹೇಳಿದಂತೆ ಅವಳು ರಾತ್ರಿಯಲ್ಲಿ ಹೋದಳು."]],
  ["ಎಲೀಮೆಲೆಕ",["ಅವನು ಯೆಹೂದದ ಬೇತ್ಲೆಹೇಮಿನವನು.","ಅವನು ಎಫ್ರಾತ್ಯನು."],["ಬರದ ನಿಮಿತ್ತ ಅವನು ಐಗುಪ್ತಕ್ಕೆ ಹೋದನು.","ಅವನು ಮೋವಾಬ್ ದೇಶಕ್ಕೆ ಹೋದನು."]],
  ["ಓಬೇದ",["ಅವನು ರೂತ ಬೋವಜರ ಮಗನು.","ನೆರೆಯ ಸ್ತ್ರೀಯರು ಅವನಿಗೆ ಹೆಸರಿಟ್ಟರು."],["ಅವನು ಅರಸನಾದ ಸೌಲನ ತಂದೆ.","ಅವನು ಇಷಯನ ತಂದೆ; ಇಷಯನು ದಾವೀದನ ತಂದೆ."]],
  ["ಹಕ್ಕಲಾಯುವ ರೂತ",["ಊಟದ ಸಮಯದಲ್ಲಿ ಕೊಯ್ಯುವವರೊಂದಿಗೆ ಹುರಿದ ತೆನೆಗಳನ್ನು ತಿಂದಳು.","ಜವೆಗೋಧಿ ಗೋಧಿಯ ಸುಗ್ಗಿ ಮುಗಿಯುವವರೆಗೆ ಹಕ್ಕಲಾಯಿದಳು."],["ಮೊದಲ ದಿನ ಸುಮಾರು ಒಂದು ಹೋಮೆರ್ ಜವೆಗೋಧಿಯನ್ನು ಕೂಡಿಸಿದಳು.","ಅವಳು ಬಡಿದಾಗ ಸುಮಾರು ಒಂದು ಏಫದಷ್ಟು ಆಯಿತು."]],
  ["ನವೊಮಿಯ ಹಿಂತಿರುಗುವಿಕೆ",["ಅವಳು ಹಿಂತಿರುಗಿದಾಗ ಊರೆಲ್ಲಾ ಗಲಿಬಿಲಿಯಾಯಿತು.","ಜವೆಗೋಧಿ ಸುಗ್ಗಿಯ ಪ್ರಾರಂಭದಲ್ಲಿ ಅವಳು ಹಿಂತಿರುಗಿದಳು."],["ಅವಳು ಒಬ್ಬಳೇ ಹಿಂತಿರುಗಿದಳು.","ರೂತಳು ಅವಳೊಂದಿಗೆ ಬಂದಳು."]],
  ["ಏಲಿ",["ಅವನು ಶೀಲೋವಿನ ಯಾಜಕನು.","ಹನ್ನಳು ಅಮಲೇರಿದ್ದಾಳೆಂದು ಅವನು ಭಾವಿಸಿದನು."],["ಅವನು ಯುದ್ಧದಲ್ಲಿ ಕತ್ತಿಯಿಂದ ಸತ್ತನು.","ಅವನು ಆಸನದಿಂದ ಹಿಂದಕ್ಕೆ ಬಿದ್ದು ಕುತ್ತಿಗೆ ಮುರಿದು ಸತ್ತನು."]],
  ["ಸಮುವೇಲ",["ಯೆಹೋವನು ರಾತ್ರಿಯಲ್ಲಿ ಅವನನ್ನು ಹೆಸರು ಹಿಡಿದು ಕರೆದನು.","ಅವನ ತಾಯಿ ಪ್ರತಿವರುಷ ಅವನಿಗೆ ಒಂದು ಸಣ್ಣ ಅಂಗಿಯನ್ನು ಮಾಡುತ್ತಿದ್ದಳು."],["ಅವನು ಸೊಲೊಮೋನನನ್ನು ಅರಸನಾಗಿ ಅಭಿಷೇಕಿಸಿದನು.","ಅವನು ಸೌಲನನ್ನೂ ದಾವೀದನನ್ನೂ ಅಭಿಷೇಕಿಸಿದನು."]],
  ["ಯೋನಾತಾನ",["ಅವನು ಅರಸನಾದ ಸೌಲನ ಮಗನು.","ಅವನು ತನ್ನ ಮೇಲಂಗಿಯನ್ನೂ ಕತ್ತಿಯನ್ನೂ ದಾವೀದನಿಗೆ ಕೊಟ್ಟನು."],["ಸೌಲನ ನಂತರ ಅವನು ಅರಸನಾದನು.","ಅವನು ಸೌಲನೊಂದಿಗೆ ಗಿಲ್ಬೋವ ಬೆಟ್ಟದಲ್ಲಿ ಸತ್ತನು."]],
  ["ಗೊಲ್ಯಾತ",["ಅವನು ಗತ್ ಊರಿನವನು.","ಅವನ ಎತ್ತರ ಆರು ಮೊಳ ಒಂದು ಗೇಣು."],["ದಾವೀದನು ಐದು ಕಲ್ಲುಗಳಿಂದ ಅವನನ್ನು ಕೊಂದನು.","ಒಂದೇ ಕಲ್ಲು ಅವನ ಹಣೆಯೊಳಗೆ ಹೊಕ್ಕಿತು."]],
  ["ಅಬೀಗೈಲ",["ಅವಳು ನಾಬಾಲನ ಹೆಂಡತಿ.","ಅವಳು ದಾವೀದನಿಗೆ ರೊಟ್ಟಿ, ದ್ರಾಕ್ಷಾರಸ, ಅಂಜೂರಗಳನ್ನು ತಂದಳು."],["ದಾವೀದನ ಬಳಿಗೆ ಹೋಗುವ ಮೊದಲು ನಾಬಾಲನಿಗೆ ಎಲ್ಲವನ್ನೂ ಹೇಳಿದಳು.","ಅವಳು ತನ್ನ ಗಂಡನಾದ ನಾಬಾಲನಿಗೆ ಹೇಳಲಿಲ್ಲ."]],
  ["ಫಿಲಿಷ್ಟಿಯರ ಬಳಿ ಮಂಜೂಷ",["ಫಿಲಿಷ್ಟಿಯರು ಅದನ್ನು ದಾಗೋನನ ಗುಡಿಯಲ್ಲಿ ಇಟ್ಟರು.","ದಾಗೋನನು ಮಂಜೂಷದ ಮುಂದೆ ಬೋರಲು ಬಿದ್ದನು."],["ಅವರು ಅದನ್ನು ಏಳು ವರುಷ ಇಟ್ಟುಕೊಂಡರು.","ಅದು ಅವರ ದೇಶದಲ್ಲಿ ಏಳು ತಿಂಗಳು ಇತ್ತು."]],
  ["ಮೀಕಲ",["ಅವಳು ಸೌಲನ ಮಗಳು.","ಅವಳು ದಾವೀದನನ್ನು ಕಿಟಕಿಯಿಂದ ಇಳಿಸಿದಳು."],["ದೂತರನ್ನು ಮೋಸಗೊಳಿಸಲು ದಾವೀದನ ಹಾಸಿಗೆಯಲ್ಲಿ ಒಂದು ಕುರಿಮರಿಯನ್ನು ಇಟ್ಟಳು.","ಅವಳು ಆಡಿನ ಕೂದಲಿನೊಂದಿಗೆ ಒಂದು ವಿಗ್ರಹವನ್ನು ಹಾಸಿಗೆಯಲ್ಲಿ ಇಟ್ಟಳು."]],
  ["ಗವಿಯಲ್ಲಿ ದಾವೀದ",["ಅವನು ಸೌಲನ ನಿಲುವಂಗಿಯ ಅಂಚನ್ನು ಕತ್ತರಿಸಿದನು.","ಯೆಹೋವನ ಅಭಿಷಿಕ್ತನ ಮೇಲೆ ಕೈಯೆತ್ತುವದಿಲ್ಲವೆಂದನು."],["ಆ ಗವಿ ಬೇತ್ಲೆಹೇಮಿನಲ್ಲಿತ್ತು.","ಅದು ಏಂಗೆದಿಯ ಅರಣ್ಯದಲ್ಲಿತ್ತು."]],
  ["ಕತ್ತೆಗಳನ್ನು ಹುಡುಕಿದ ಸೌಲ",["ಅವನು ತನ್ನ ತಂದೆಯ ತಪ್ಪಿಹೋದ ಕತ್ತೆಗಳನ್ನು ಹುಡುಕುತ್ತಿದ್ದನು.","ಅವನು ಜನರೆಲ್ಲರಿಗಿಂತ ಎತ್ತರವಾಗಿದ್ದನು."],["ಸಮುವೇಲನನ್ನು ಭೇಟಿಯಾಗುವ ಮೊದಲೇ ಅವನಿಗೆ ಕತ್ತೆಗಳು ಸಿಕ್ಕಿದವು.","ಕತ್ತೆಗಳು ಸಿಕ್ಕಿವೆ ಎಂದು ಸಮುವೇಲನೇ ಅವನಿಗೆ ಹೇಳಿದನು."]],
  ["ಏಂದೋರಿನಲ್ಲಿ ಸೌಲ",["ಅವನು ಯಕ್ಷಿಣಿಯುಳ್ಳ ಒಬ್ಬ ಸ್ತ್ರೀಯನ್ನು ಹುಡುಕಿದನು.","ಹೋಗುವ ಮೊದಲು ಅವನು ವೇಷಮರೆಸಿಕೊಂಡನು."],["ಅವನು ಯುದ್ಧದಲ್ಲಿ ಜಯಿಸುವನೆಂದು ಸಮುವೇಲನು ಹೇಳಿದನು.","ಯೆಹೋವನು ಇಸ್ರಾಯೇಲ್ಯರನ್ನು ಫಿಲಿಷ್ಟಿಯರ ಕೈಗೆ ಒಪ್ಪಿಸುವನೆಂದು ಸಮುವೇಲನು ಹೇಳಿದನು."]],
  ["ಮೊರ್ದೆಕೈ",["ಅರಸನನ್ನು ಕೊಲ್ಲುವ ಒಳಸಂಚನ್ನು ಅವನು ಬಯಲುಪಡಿಸಿದನು.","ಅವನು ಹಾಮಾನನಿಗೆ ಅಡ್ಡಬೀಳಲಿಲ್ಲ."],["ಅವನನ್ನು ಗಲ್ಲಿನ ಮರಕ್ಕೆ ಹಾಕಿದರು.","ಮೊರ್ದೆಕೈಗಾಗಿ ತಾನು ಮಾಡಿಸಿದ ಗಲ್ಲಿನ ಮರಕ್ಕೆ ಹಾಮಾನನನ್ನೇ ಹಾಕಿದರು."]],
  ["ಹಾಮಾನ",["ಅವನು ಅಗಾಗ್ಯನು.","ದಿನವನ್ನು ಆರಿಸಲು ಅವನು ಪೂರ್ ಎಂಬ ಚೀಟನ್ನು ಹಾಕಿಸಿದನು."],["ತನಗೆ ಇಷ್ಟವಿದ್ದದರಿಂದ ಮೊರ್ದೆಕೈಯನ್ನು ಅರಸನ ಕುದುರೆಯ ಮೇಲೆ ಕರೆದುಕೊಂಡು ಹೋದನು.","ಅರಸನು ಹಾಗೆ ಮಾಡಬೇಕೆಂದು ಅವನಿಗೆ ಆಜ್ಞಾಪಿಸಿದನು."]],
  ["ವಷ್ಟಿ",["ಎಸ್ತೇರಳಿಗಿಂತ ಮೊದಲು ಅವಳು ರಾಣಿಯಾಗಿದ್ದಳು.","ಅವಳು ಸ್ತ್ರೀಯರಿಗೆ ಔತಣ ಮಾಡಿಸಿದಳು."],["ಅರಸನು ಕರೆದಾಗ ಅವಳು ಸಂತೋಷವಾಗಿ ಬಂದಳು.","ಅರಸನ ಆಜ್ಞೆಯಂತೆ ಬರಲು ಅವಳು ನಿರಾಕರಿಸಿದಳು."]],
  ["ಅರಸನಾದ ಅಹಷ್ವೇರೋಷ",["ಅವನು ಹಿಂದೂ ದೇಶದಿಂದ ಕೂಷ್ ದೇಶದವರೆಗೆ ಆಳಿದನು.","ನಿದ್ರೆ ಬಾರದೆ ಇದ್ದುದರಿಂದ ವೃತ್ತಾಂತಗಳ ಪುಸ್ತಕವನ್ನು ಓದಿಸಿದನು."],["ಅವನು ನೂರು ಪ್ರಾಂತ್ಯಗಳನ್ನು ಆಳಿದನು.","ಅವನು ನೂರ ಇಪ್ಪತ್ತೇಳು ಪ್ರಾಂತ್ಯಗಳನ್ನು ಆಳಿದನು."]],
  ["ಎಸ್ತೇರಳ ಉಪವಾಸ",["ತನಗಾಗಿ ಉಪವಾಸ ಮಾಡಬೇಕೆಂದು ಶೂಷನಿನ ಯೆಹೂದ್ಯರನ್ನು ಕೇಳಿಕೊಂಡಳು.","ನಾನು ನಾಶವಾದರೆ ನಾಶವಾಗುವೆನು ಎಂದಳು."],["ಆ ಉಪವಾಸವು ನಾಲ್ವತ್ತು ದಿನ ನಡೆಯಿತು.","ಅವರು ಹಗಲೂ ರಾತ್ರಿಯೂ ಮೂರು ದಿನ ಉಪವಾಸ ಮಾಡಿದರು."]],
  ["ಎಸ್ತೇರಳ ಔತಣಗಳು",["ಅರಸನು ಬಂಗಾರದ ರಾಜದಂಡವನ್ನು ಅವಳ ಕಡೆಗೆ ಚಾಚಿದನು.","ಅವಳು ಅರಸನನ್ನೂ ಹಾಮಾನನನ್ನೂ ಔತಣಕ್ಕೆ ಕರೆದಳು."],["ಮೊದಲನೆಯ ಔತಣದಲ್ಲೇ ಅವಳು ಹಾಮಾನನ ವಿಷಯ ಅರಸನಿಗೆ ಹೇಳಿದಳು.","ಎರಡನೆಯ ಔತಣದಲ್ಲಿ ಅವಳು ಹೇಳಿದಳು."]],
  ["ಪೂರೀಮ್ ಹಬ್ಬ",["ಅದನ್ನು ಅದಾರ್ ತಿಂಗಳ ಹದಿನಾಲ್ಕು ಹದಿನೈದನೆಯ ದಿನಗಳಲ್ಲಿ ಆಚರಿಸುತ್ತಾರೆ.","ಪೂರ್ ಎಂಬ ಚೀಟಿನಿಂದ ಅದಕ್ಕೆ ಆ ಹೆಸರು ಬಂತು."],["ಬಾಬೆಲಿನಿಂದ ಹಿಂತಿರುಗಿದ್ದನ್ನು ಅದು ಆಚರಿಸುತ್ತದೆ.","ಹಾಮಾನನಿಂದ ಯೆಹೂದ್ಯರು ರಕ್ಷಿಸಲ್ಪಟ್ಟದ್ದನ್ನು ಅದು ನೆನಪಿಸುತ್ತದೆ."]],
  ["ಹಾಮಾನನ ಸಂಚು",["ಅವನು ಹತ್ತು ಸಾವಿರ ತಲಾಂತು ಬೆಳ್ಳಿಯನ್ನು ಕೊಡುವೆನೆಂದನು.","ಅವನು ಐವತ್ತು ಮೊಳ ಎತ್ತರದ ಗಲ್ಲಿನ ಮರವನ್ನು ಮಾಡಿಸಿದನು."],["ಮೊರ್ದೆಕೈಯನ್ನು ಮಾತ್ರ ನಾಶಮಾಡಬೇಕೆಂದು ಅವನು ಸಂಚುಮಾಡಿದನು.","ಎಲ್ಲಾ ಯೆಹೂದ್ಯರನ್ನು ನಾಶಮಾಡಲು ಅವನು ಹುಡುಕಿದನು."]],
  ["ಎಸ್ತೇರಳ ಸಿದ್ಧತೆ",["ಅದು ಹನ್ನೆರಡು ತಿಂಗಳು ನಡೆಯಿತು.","ಸ್ತ್ರೀಯರ ಮೇಲ್ವಿಚಾರಕನಾದ ಹೇಗ್ಯನು ಅವಳಿಗೆ ದಯೆತೋರಿಸಿದನು."],["ತಾನು ಯೆಹೂದ್ಯಳೆಂದು ಎಲ್ಲರಿಗೂ ಹೇಳಿದಳು.","ತನ್ನ ಜನಾಂಗವನ್ನು ಹೇಳಬಾರದೆಂದು ಮೊರ್ದೆಕೈ ಅವಳಿಗೆ ಆಜ್ಞಾಪಿಸಿದ್ದನು."]],
  ["ಜೆರೆಷ",["ಅವಳು ಹಾಮಾನನ ಹೆಂಡತಿ.","ಗಲ್ಲಿನ ಮರವನ್ನು ಮಾಡಿಸಬೇಕೆಂದು ಅವಳು ಸಲಹೆಕೊಟ್ಟಳು."],["ಹಾಮಾನನ ಸಂಚಿನ ವಿಷಯ ಅವಳು ಮೊರ್ದೆಕೈಗೆ ಎಚ್ಚರಿಸಿದಳು.","ಆಜ್ಞೆ ಪ್ರಕಟವಾದಾಗ ಮೊರ್ದೆಕೈಗೆ ತಿಳಿಯಿತು."]],
  ["ಶದ್ರಕ್, ಮೇಶಕ್, ಅಬೇದ್ನೆಗೋ",["ಅವರ ಇಬ್ರಿಯ ಹೆಸರುಗಳು ಹನನ್ಯ, ಮೀಶಾಯೇಲ, ಅಜರ್ಯ.","ಅವರು ಬಂಗಾರದ ಪ್ರತಿಮೆಗೆ ಅಡ್ಡಬೀಳಲಿಲ್ಲ."],["ಬೆಂಕಿ ಅವರ ಅಂಗಿಗಳನ್ನು ಸುಟ್ಟಿತು, ಆದರೆ ದೇಹಗಳನ್ನು ಸುಡಲಿಲ್ಲ.","ಅವರ ಒಂದು ಕೂದಲೂ ಸುಡಲಿಲ್ಲ; ಬೆಂಕಿಯ ವಾಸನೆಯೂ ಅವರ ಮೇಲೆ ಇರಲಿಲ್ಲ."]],
  ["ನೆಬೂಕದ್ನೆಚ್ಚರ",["ಅವನು ಒಂದು ದೊಡ್ಡ ಪ್ರತಿಮೆಯ ಕನಸು ಕಂಡನು.","ಅವನು ಎತ್ತುಗಳಂತೆ ಹುಲ್ಲು ತಿಂದನು."],["ಗೋಡೆಯ ಮೇಲಿನ ಕೈಬರಹವನ್ನು ಅವನು ನೋಡಿದನು.","ಅದನ್ನು ನೋಡಿದವನು ಬೇಲ್ಶಚ್ಚರನು."]],
  ["ಬೇಲ್ಶಚ್ಚರ",["ದೇವಾಲಯದ ಬಂಗಾರದ ಪಾತ್ರೆಗಳಲ್ಲಿ ಅವನು ದ್ರಾಕ್ಷಾರಸವನ್ನು ಕುಡಿದನು.","ದಾನಿಯೇಲನನ್ನು ರಾಜ್ಯದಲ್ಲಿ ಮೂರನೆಯ ಅಧಿಕಾರಿಯನ್ನಾಗಿ ಮಾಡಿದನು."],["ಆ ರಾತ್ರಿಯ ನಂತರ ಅವನು ಅನೇಕ ವರುಷ ಆಳಿದನು.","ಅದೇ ರಾತ್ರಿ ಅವನು ಕೊಲ್ಲಲ್ಪಟ್ಟನು."]],
  ["ಅರಸನಾದ ದಾರ್ಯಾವೆಷ",["ರಾಜ್ಯದ ಮೇಲೆ ನೂರಿಪ್ಪತ್ತು ಅಧಿಪತಿಗಳನ್ನು ನೇಮಿಸಿದನು.","ದಾನಿಯೇಲನು ಗವಿಯಲ್ಲಿದ್ದಾಗ ಅವನು ರಾತ್ರಿಯೆಲ್ಲಾ ಉಪವಾಸವಿದ್ದನು."],["ದಾನಿಯೇಲನನ್ನು ದ್ವೇಷಿಸಿದ್ದರಿಂದ ಅವನನ್ನು ಸಿಂಹಗಳಿಗೆ ಹಾಕಿಸಿದನು.","ಅವನು ಬಹಳ ವ್ಯಸನಪಟ್ಟು ದಾನಿಯೇಲನನ್ನು ಬಿಡಿಸಲು ಪ್ರಯಾಸಪಟ್ಟನು."]],
  ["ದಾನಿಯೇಲನ ಆಹಾರ",["ಅರಸನ ಭೋಜನದಿಂದ ತನ್ನನ್ನು ಅಶುದ್ಧಮಾಡಿಕೊಳ್ಳಲಿಲ್ಲ.","ತಿನ್ನಲು ಕಾಳುಗಳನ್ನೂ ಕುಡಿಯಲು ನೀರನ್ನೂ ಕೇಳಿದನು."],["ಆ ಪರೀಕ್ಷೆ ನಾಲ್ವತ್ತು ದಿನ ನಡೆಯಿತು.","ಆ ಪರೀಕ್ಷೆ ಹತ್ತು ದಿನ ನಡೆಯಿತು."]],
  ["ಕನಸಿನ ಪ್ರತಿಮೆ",["ಅದರ ತಲೆ ಶುದ್ಧ ಬಂಗಾರದ್ದು.","ಅದರ ಪಾದಗಳು ಸ್ವಲ್ಪ ಕಬ್ಬಿಣ ಸ್ವಲ್ಪ ಮಣ್ಣಿನವು."],["ದೊಡ್ಡ ಜಲಪ್ರಳಯವು ಅದನ್ನು ನಾಶಮಾಡಿತು.","ಕೈಹಾಕದೆ ಕಡಿಯಲ್ಪಟ್ಟ ಒಂದು ಕಲ್ಲು ಅದನ್ನು ಹೊಡೆಯಿತು."]],
  ["ಗೋಡೆಯ ಮೇಲಿನ ಬರಹ",["ಆ ಮಾತುಗಳು ಮೆನೇ, ಮೆನೇ, ತೆಕೇಲ್, ಉಫಾರ್ಸೀನ್.","ಮನುಷ್ಯನ ಕೈಯ ಬೆರಳುಗಳು ಅದನ್ನು ಬರೆದವು."],["ಅರಸನ ಜ್ಞಾನಿಗಳು ಅದನ್ನು ಸುಲಭವಾಗಿ ಓದಿದರು.","ಅವರಿಗೆ ಓದಲಾಗಲಿಲ್ಲ; ದಾನಿಯೇಲನು ಓದಿದನು."]],
  ["ದಾನಿಯೇಲನ ದರ್ಶನಗಳು",["ಸಮುದ್ರದೊಳಗಿಂದ ನಾಲ್ಕು ದೊಡ್ಡ ಮೃಗಗಳು ಬರುವದನ್ನು ಕಂಡನು.","ಸಾಯಂಕಾಲದ ನೈವೇದ್ಯದ ಸಮಯದಲ್ಲಿ ಗಬ್ರಿಯೇಲನು ಅವನ ಬಳಿಗೆ ಬಂದನು."],["ಏಳು ತಲೆಗಳುಳ್ಳ ಒಂದು ಸಿಂಹವನ್ನು ಕಂಡನು.","ಮೊದಲನೆಯ ಮೃಗವು ಹದ್ದಿನ ರೆಕ್ಕೆಗಳುಳ್ಳ ಸಿಂಹದಂತಿತ್ತು."]],
  ["ಸಿಂಹಗಳ ಗವಿ",["ದಾನಿಯೇಲನು ಯೆರೂಸಲೇಮಿನ ಕಡೆಗೆ ಕಿಟಕಿಗಳನ್ನು ತೆರೆದು ಪ್ರಾರ್ಥಿಸಿದನು.","ದೇವರು ತನ್ನ ದೂತನನ್ನು ಕಳುಹಿಸಿ ಸಿಂಹಗಳ ಬಾಯಿಗಳನ್ನು ಮುಚ್ಚಿದನು."],["ದಾನಿಯೇಲನು ಮೂರು ದಿನ ಗವಿಯಲ್ಲಿದ್ದನು.","ಮರುದಿನ ಬಹಳ ಬೆಳಿಗ್ಗೆ ಅರಸನು ಗವಿಯ ಬಳಿಗೆ ಹೋದನು."]],
  ["ಉರಿಯುವ ಆವಿಗೆ",["ಅದನ್ನು ವಾಡಿಕೆಗಿಂತ ಏಳರಷ್ಟು ಹೆಚ್ಚಾಗಿ ಕಾಯಿಸಿದರು.","ಬೆಂಕಿಯಲ್ಲಿ ನಾಲ್ಕು ಮಂದಿ ತಿರುಗಾಡುವದನ್ನು ಅರಸನು ಕಂಡನು."],["ಆ ಜ್ವಾಲೆಗಳಿಂದ ಯಾರೂ ಸಾಯಲಿಲ್ಲ.","ಅವರನ್ನು ಒಳಗೆ ಹಾಕಿದವರನ್ನು ಜ್ವಾಲೆಯು ಕೊಂದಿತು."]],
  ["ಜ್ಞಾನಿಗಳು",["ಅವರು ಮೂಡಣ ದಿಕ್ಕಿನಿಂದ ನಕ್ಷತ್ರವನ್ನು ಹಿಂಬಾಲಿಸಿ ಬಂದರು.","ಅವರು ಬಂಗಾರ, ಧೂಪ, ರಕ್ತಬೋಳ ತಂದರು."],["ಅವರು ಮೂರು ಮಂದಿ ಎಂದು ಸತ್ಯವೇದ ಹೇಳುತ್ತದೆ.","ಜ್ಞಾನಿಗಳ ಸಂಖ್ಯೆಯನ್ನು ಎಲ್ಲಿಯೂ ಹೇಳಿಲ್ಲ."]],
  ["ಮರಿಯಳ ಗಂಡನಾದ ಯೋಸೇಫ",["ಕನಸಿನಲ್ಲಿ ದೂತನು ಅವನೊಂದಿಗೆ ಮಾತನಾಡಿದನು.","ಅವನು ಕುಟುಂಬವನ್ನು ಐಗುಪ್ತಕ್ಕೆ ಕರೆದುಕೊಂಡು ಹೋದನು."],["ಅವನು ಬೆಸ್ತನಾಗಿದ್ದನು.","ಅವನು ಬಡಗಿಯಾಗಿದ್ದನು."]],
  ["ಇಸ್ಕರಿಯೋತ ಯೂದ",["ಅವನಿಗೆ ಮೂವತ್ತು ಬೆಳ್ಳಿ ನಾಣ್ಯಗಳನ್ನು ಕೊಟ್ಟರು.","ಅವನು ಮುದ್ದಿಟ್ಟು ಯೇಸುವನ್ನು ಹಿಡಿದುಕೊಟ್ಟನು."],["ಮಹಾಯಾಜಕರು ಆ ಬೆಳ್ಳಿಯನ್ನು ಕಾಣಿಕೆಯ ಪೆಟ್ಟಿಗೆಯಲ್ಲಿ ಹಾಕಿದರು.","ಅದು ರಕ್ತದ ಕ್ರಯವಾದ್ದರಿಂದ ಅವರು ಕುಂಬಾರನ ಹೊಲವನ್ನು ಕೊಂಡರು."]],
  ["ಪೊಂತ್ಯ ಪಿಲಾತ",["ಕನಸಿನ ವಿಷಯವಾಗಿ ಅವನ ಹೆಂಡತಿ ಅವನಿಗೆ ಹೇಳಿಕಳುಹಿಸಿದಳು.","ಜನರ ಮುಂದೆ ಅವನು ಕೈ ತೊಳೆದುಕೊಂಡನು."],["ಅವನು ಯೇಸುವನ್ನು ಬಿಡುಗಡೆಮಾಡಿ ಬರಬ್ಬನನ್ನು ಇಟ್ಟುಕೊಂಡನು.","ಅವನು ಬರಬ್ಬನನ್ನು ಬಿಡುಗಡೆಮಾಡಿದನು."]],
  ["ಯೇಸುವಿನ ಶೋಧನೆ",["ಯೇಸು ನಾಲ್ವತ್ತು ದಿನ ನಾಲ್ವತ್ತು ರಾತ್ರಿ ಉಪವಾಸವಿದ್ದನು.","ಸೈತಾನನು ಆತನನ್ನು ದೇವಾಲಯದ ಶಿಖರದ ಮೇಲೆ ನಿಲ್ಲಿಸಿದನು."],["ಯೇಸು ಒಂದು ಕಲ್ಲನ್ನು ರೊಟ್ಟಿಯನ್ನಾಗಿ ಮಾಡಿದನು.","ಮನುಷ್ಯನು ರೊಟ್ಟಿಯಿಂದ ಮಾತ್ರವೇ ಬದುಕುವದಿಲ್ಲ ಎಂದು ಆತನು ಉತ್ತರಕೊಟ್ಟನು."]],
  ["ತಲಾಂತುಗಳ ಸಾಮ್ಯ",["ಒಬ್ಬ ಆಳಿಗೆ ಐದು ತಲಾಂತುಗಳನ್ನು ಕೊಟ್ಟನು.","ಒಬ್ಬ ಆಳು ತನ್ನ ತಲಾಂತನ್ನು ಭೂಮಿಯಲ್ಲಿ ಬಚ್ಚಿಟ್ಟನು."],["ಒಂದು ತಲಾಂತು ಹೊಂದಿದ್ದವನು ಅದನ್ನು ಎರಡರಷ್ಟು ಮಾಡಿದನು.","ಅವನು ಅದನ್ನು ಬಚ್ಚಿಟ್ಟು ಅದೇ ಒಂದನ್ನು ಹಿಂತಿರುಗಿಸಿದನು."]],
  ["ಹತ್ತು ಮಂದಿ ಕನ್ಯೆಯರು",["ಐದು ಮಂದಿ ಬುದ್ಧಿವಂತೆಯರು, ಐದು ಮಂದಿ ಬುದ್ಧಿಹೀನೆಯರು.","ಬುದ್ಧಿಹೀನೆಯರು ತಮ್ಮ ದೀಪಗಳೊಂದಿಗೆ ಎಣ್ಣೆ ತಕ್ಕೊಳ್ಳಲಿಲ್ಲ."],["ಬುದ್ಧಿವಂತೆಯರು ತಮ್ಮ ಎಣ್ಣೆಯನ್ನು ಬುದ್ಧಿಹೀನೆಯರೊಂದಿಗೆ ಹಂಚಿಕೊಂಡರು.","ಮಾರುವವರ ಬಳಿಗೆ ಹೋಗಿ ಕೊಂಡುಕೊಳ್ಳಿರಿ ಎಂದು ಬುದ್ಧಿವಂತೆಯರು ಹೇಳಿದರು."]],
  ["ಶಿಲುಬೆಗೆ ಹಾಕಿದ್ದು",["ಕುರೇನ್ಯನಾದ ಸೀಮೋನನು ಶಿಲುಬೆಯನ್ನು ಹೊತ್ತನು.","ದೇಶದ ಮೇಲೆಲ್ಲಾ ಕತ್ತಲೆ ಕವಿಯಿತು."],["ಯೇಸುವನ್ನು ಒಬ್ಬನನ್ನೇ ಶಿಲುಬೆಗೆ ಹಾಕಿದರು.","ಆತನೊಂದಿಗೆ ಇಬ್ಬರು ಕಳ್ಳರನ್ನೂ ಶಿಲುಬೆಗೆ ಹಾಕಿದರು."]],
  ["ಪರ್ವತ ಪ್ರಸಂಗ",["ಯೇಸು ಕರ್ತನ ಪ್ರಾರ್ಥನೆಯನ್ನು ಕಲಿಸಿದನು.","ನೀವು ಲೋಕಕ್ಕೆ ಬೆಳಕಾಗಿದ್ದೀರಿ ಎಂದು ಆತನು ಹೇಳಿದನು."],["ಯೇಸು ಅದನ್ನು ದೋಣಿಯಲ್ಲಿ ಕುಳಿತು ಸಾರಿದನು.","ಆತನು ಬೆಟ್ಟವನ್ನು ಹತ್ತಿ ಕುಳಿತುಕೊಂಡನು."]],
  ["ಪುನರುತ್ಥಾನದ ಮುಂಜಾನೆ",["ದೊಡ್ಡ ಭೂಕಂಪವಾಯಿತು.","ದೂತನು ಆ ಕಲ್ಲಿನ ಮೇಲೆ ಕುಳಿತುಕೊಂಡನು."],["ಕಾವಲುಗಾರರು ಶಿಷ್ಯರಿಗೆ ತಿಳಿಸಲು ಓಡಿಹೋದರು.","ಕಾವಲುಗಾರರು ಮಹಾಯಾಜಕರಿಗೆ ತಿಳಿಸಿದರು; ಸುಳ್ಳು ಹೇಳಲು ಅವರಿಗೆ ಹಣ ಕೊಟ್ಟರು."]],
  ["ಜಕರೀಯ",["ಅವನು ಯಾಜಕನು.","ಅವನ ಹೆಸರು ಯೋಹಾನ ಎಂದು ಬರೆದನು."],["ಅವನು ದೂತನನ್ನು ನೋಡಿ ನಕ್ಕನು.","ಅವನು ನಂಬದೆ ಹೋದದ್ದರಿಂದ ಮೂಕನಾದನು."]],
  ["ಎಲಿಸಬೇತ",["ಅವಳು ಮರಿಯಳ ಬಂಧು.","ಅವಳು ಆರೋನನ ವಂಶದವಳು."],["ಅವಳು ತನ್ನ ಮಗನಿಗೆ ಜಕರೀಯ ಎಂದು ಹೆಸರಿಟ್ಟಳು.","ಹಾಗಲ್ಲ, ಯೋಹಾನನೆಂದು ಹೆಸರಿಡಬೇಕು ಎಂದಳು."]],
  ["ಕುರುಬರು",["ಅವರು ರಾತ್ರಿಯಲ್ಲಿ ತಮ್ಮ ಮಂದೆಯನ್ನು ಕಾಯುತ್ತಿದ್ದರು.","ಕೂಸು ಗೋದಲಿಯಲ್ಲಿ ಮಲಗಿರುವದನ್ನು ಕಂಡರು."],["ನಕ್ಷತ್ರವನ್ನು ಹಿಂಬಾಲಿಸಿ ಅವರು ಬೇತ್ಲೆಹೇಮಿಗೆ ಹೋದರು.","ದೂತನು ಅವರಿಗೆ ಗುರುತನ್ನು ಹೇಳಿದನು."]],
  ["ಸಿಮೆಯೋನ",["ಕರ್ತನ ಕ್ರಿಸ್ತನನ್ನು ನೋಡುವನೆಂದು ಅವನಿಗೆ ಪ್ರಕಟವಾಗಿತ್ತು.","ಅವನು ಕೂಸಾದ ಯೇಸುವನ್ನು ತೋಳುಗಳಲ್ಲಿ ಎತ್ತಿಕೊಂಡನು."],["ಅವನು ಮಹಾಯಾಜಕನು.","ಅವನು ನೀತಿವಂತನೂ ಭಕ್ತನೂ; ಅವನನ್ನು ಯಾಜಕನೆಂದು ಹೇಳಿಲ್ಲ."]],
  ["ಒಳ್ಳೇ ಸಮಾರ್ಯದವನು",["ಅವನು ಎಣ್ಣೆಯನ್ನೂ ದ್ರಾಕ್ಷಾರಸವನ್ನೂ ಹೊಯ್ದನು.","ಛತ್ರದವನಿಗೆ ಎರಡು ಪಾವಲಿಗಳನ್ನು ಕೊಟ್ಟನು."],["ಅವನಿಗಿಂತ ಮೊದಲು ಒಬ್ಬ ಲೇವಿಯನು ನಿಂತು ಸಹಾಯಮಾಡಿದನು.","ಯಾಜಕನೂ ಲೇವಿಯನೂ ಆಚೆ ಬದಿಯಿಂದ ಹೊರಟುಹೋದರು."]],
  ["ದುಂದುಗಾರ ಮಗನು",["ಆಸ್ತಿಯಲ್ಲಿ ತನ್ನ ಪಾಲನ್ನು ಕೇಳಿದನು.","ದೂರ ದೇಶದಲ್ಲಿ ಅವನು ಹಂದಿಗಳನ್ನು ಮೇಯಿಸಿದನು."],["ಅವನು ಕ್ಷಮೆಕೇಳುವವರೆಗೆ ತಂದೆ ಕಾದು ನಂತರ ಓಡಿಬಂದನು.","ಅವನು ಇನ್ನೂ ದೂರದಲ್ಲಿರುವಾಗಲೇ ತಂದೆ ಕಂಡು ಓಡಿಬಂದನು."]],
  ["ಬುದ್ಧಿಹೀನ ಐಶ್ವರ್ಯವಂತ",["ಅವನ ಭೂಮಿ ಬಹಳವಾಗಿ ಬೆಳೆಯಿತು.","ನನ್ನ ಕಣಜಗಳನ್ನು ಕೆಡವಿ ದೊಡ್ಡವುಗಳನ್ನು ಕಟ್ಟುವೆನು ಎಂದನು."],["ತನ್ನ ಸಂಪತ್ತನ್ನು ಅನುಭವಿಸಲು ದೇವರು ಅವನಿಗೆ ಇನ್ನೂ ಅನೇಕ ವರುಷ ಕೊಟ್ಟನು.","ಈ ರಾತ್ರಿಯೇ ನಿನ್ನ ಪ್ರಾಣವನ್ನು ಕೇಳುವರು ಎಂದು ದೇವರು ಹೇಳಿದನು."]],
  ["ಹತ್ತು ಮಂದಿ ಕುಷ್ಠರೋಗಿಗಳು",["ಅವರು ದೂರದಲ್ಲಿ ನಿಂತು ಕರುಣೆಗಾಗಿ ಕೂಗಿದರು.","ಅವರು ಹೋಗುತ್ತಿರುವಾಗಲೇ ಶುದ್ಧರಾದರು."],["ಹತ್ತು ಮಂದಿಯೂ ಸ್ತೋತ್ರಮಾಡಲು ಹಿಂತಿರುಗಿ ಬಂದರು.","ಒಬ್ಬನೇ ಹಿಂತಿರುಗಿ ಬಂದನು; ಅವನು ಸಮಾರ್ಯದವನು."]],
  ["ಎಮ್ಮಾಹು ದಾರಿ",["ಆ ಇಬ್ಬರು ಶಿಷ್ಯರಲ್ಲಿ ಒಬ್ಬನ ಹೆಸರು ಕ್ಲಿಯೊಫಾಸ.","ಆತನು ರೊಟ್ಟಿ ಮುರಿದಾಗ ಅವರು ಆತನನ್ನು ಗುರುತಿಸಿದರು."],["ಎಮ್ಮಾಹು ಯೆರೂಸಲೇಮಿನಿಂದ ನೂರು ಮೈಲಿ ದೂರದಲ್ಲಿತ್ತು.","ಅದು ಸುಮಾರು ಅರುವತ್ತು ಫರ್ಲಾಂಗು ದೂರದಲ್ಲಿತ್ತು."]],
  ["ಶಿಲುಬೆಯ ಮೇಲಿನ ಕಳ್ಳ",["ಅವನು ಮತ್ತೊಬ್ಬ ಕಳ್ಳನನ್ನು ಗದರಿಸಿದನು.","ಕರ್ತನೇ, ನನ್ನನ್ನು ಜ್ಞಾಪಕಮಾಡಿಕೋ ಎಂದನು."],["ನಾಳೆ ನನ್ನೊಂದಿಗೆ ಇರುವಿ ಎಂದು ಯೇಸು ಹೇಳಿದನು.","ಈ ಹೊತ್ತೇ ನೀನು ನನ್ನ ಸಂಗಡ ಪರದೈಸಿನಲ್ಲಿರುವಿ ಎಂದು ಯೇಸು ಹೇಳಿದನು."]],
  ["ಅಂದ್ರೆಯ",["ಅವನು ಮೊದಲು ಸ್ನಾನಿಕನಾದ ಯೋಹಾನನ ಶಿಷ್ಯನಾಗಿದ್ದನು.","ಅವನು ತನ್ನ ಸಹೋದರನಾದ ಸೀಮೋನನನ್ನು ಯೇಸುವಿನ ಬಳಿಗೆ ಕರೆತಂದನು."],["ಅವನು ಯಾಕೋಬನ ಸಹೋದರನು.","ಅವನು ಸೀಮೋನ ಪೇತ್ರನ ಸಹೋದರನು."]],
  ["ನತಾನಯೇಲ",["ಯೇಸು ಅವನನ್ನು ಅಂಜೂರದ ಮರದ ಕೆಳಗೆ ಕಂಡನು.","ನೀನು ದೇವರ ಮಗನು ಎಂದು ಅವನು ಹೇಳಿದನು."],["ಅವನು ನಜರೇತಿನವನು.","ನಜರೇತಿನಿಂದ ಒಳ್ಳೇದು ಬರುವದೋ ಎಂದು ಕೇಳಿದವನು; ಅವನು ಕಾನಾ ಊರಿನವನು."]],
  ["ಬಾವಿಯ ಬಳಿಯ ಸ್ತ್ರೀ",["ಯಾಕೋಬನ ಬಾವಿಗೆ ನೀರು ಸೇದಲು ಬಂದಳು.","ಅವಳು ತನ್ನ ಕೊಡವನ್ನು ಬಿಟ್ಟು ಊರೊಳಗೆ ಹೋದಳು."],["ಅವಳಿಗೆ ಒಂದೇ ಸಾರಿ ಮದುವೆಯಾಗಿತ್ತು.","ಅವಳಿಗೆ ಐದು ಮಂದಿ ಗಂಡಂದಿರು ಇದ್ದರೆಂದು ಯೇಸು ಹೇಳಿದನು."]],
  ["ಕಾನಾ ಊರಿನ ಮದುವೆ",["ಯೇಸುವಿನ ತಾಯಿ ಅಲ್ಲಿದ್ದಳು.","ಆರು ಕಲ್ಲಿನ ಬಾನೆಗಳು ಇದ್ದವು."],["ಹೊಸ ದ್ರಾಕ್ಷಾರಸ ಮೊದಲಿನದಕ್ಕಿಂತ ಕೆಟ್ಟದು ಎಂದು ಔತಣದ ಮೇಲ್ವಿಚಾರಕನು ಹೇಳಿದನು.","ಒಳ್ಳೇ ದ್ರಾಕ್ಷಾರಸವನ್ನು ಇಲ್ಲಿಯವರೆಗೆ ಇಟ್ಟಿದ್ದೀ ಎಂದು ಅವನು ಹೇಳಿದನು."]],
  ["ಹುಟ್ಟುಕುರುಡ",["ಯೇಸು ಕೆಸರು ಮಾಡಿ ಅವನ ಕಣ್ಣುಗಳಿಗೆ ಹಚ್ಚಿದನು.","ಅವನು ಸಿಲೋವ ಕೊಳದಲ್ಲಿ ತೊಳೆದುಕೊಂಡನು."],["ಯೇಸು ಅವನನ್ನು ಗುಣಪಡಿಸಿದನೆಂದು ಅವನ ತಂದೆತಾಯಿಗಳು ಸಂತೋಷದಿಂದ ಫರಿಸಾಯರಿಗೆ ಹೇಳಿದರು.","ಯೆಹೂದ್ಯರಿಗೆ ಹೆದರಿ ಅವನು ಪ್ರಾಯದವನು, ಅವನನ್ನೇ ಕೇಳಿರಿ ಎಂದರು."]],
  ["ಬೇಥಾನ್ಯದ ಮರಿಯಳು",["ಅವಳು ಯೇಸುವಿನ ಪಾದಗಳಿಗೆ ತೈಲ ಹಚ್ಚಿದಳು.","ಅವಳು ತನ್ನ ತಲೆಕೂದಲಿನಿಂದ ಆತನ ಪಾದಗಳನ್ನು ಒರಸಿದಳು."],["ತೈಲ ವ್ಯರ್ಥವಾಯಿತೆಂದು ಪೇತ್ರನು ಗುಣುಗುಟ್ಟಿದನು.","ಇಸ್ಕರಿಯೋತ ಯೂದನೇ ಗುಣುಗುಟ್ಟಿದನು."]],
  ["ಮಗ್ದಲದ ಮರಿಯಳು",["ಇನ್ನೂ ಕತ್ತಲಿರುವಾಗಲೇ ಅವಳು ಸಮಾಧಿಯ ಬಳಿಗೆ ಬಂದಳು.","ಯೇಸುವನ್ನು ತೋಟಗಾರನೆಂದು ಅವಳು ನೆನಸಿದಳು."],["ಮುಖ ನೋಡಿದ ಕೂಡಲೇ ಅವಳು ಯೇಸುವನ್ನು ಗುರುತಿಸಿದಳು.","ಆತನು ಅವಳನ್ನು ಹೆಸರು ಹಿಡಿದು ಕರೆದಾಗ ಗುರುತಿಸಿದಳು."]],
  ["ಯೇಸು ಪ್ರೀತಿಸಿದ ಶಿಷ್ಯ",["ಊಟದಲ್ಲಿ ಅವನು ಯೇಸುವಿನ ಎದೆಗೆ ಒರಗಿಕೊಂಡಿದ್ದನು.","ಯೇಸು ತನ್ನ ತಾಯಿಯನ್ನು ಅವನ ಆರೈಕೆಗೆ ಒಪ್ಪಿಸಿದನು."],["ಅವನು ಪೇತ್ರನ ನಂತರ ಸಮಾಧಿಗೆ ಬಂದನು.","ಅವನು ಪೇತ್ರನಿಗಿಂತ ಮುಂದಾಗಿ ಓಡಿ ಮೊದಲು ಬಂದನು."]],
  ["ಐದು ಸಾವಿರ ಜನರಿಗೆ ಊಟ",["ಒಬ್ಬ ಹುಡುಗನ ಬಳಿ ಐದು ಜವೆಗೋಧಿ ರೊಟ್ಟಿ ಎರಡು ಸಣ್ಣ ಮೀನುಗಳು ಇದ್ದವು.","ಹನ್ನೆರಡು ಪುಟ್ಟಿ ತುಂಡುಗಳನ್ನು ಕೂಡಿಸಿದರು."],["ರೊಟ್ಟಿಯುಳ್ಳ ಹುಡುಗನನ್ನು ಪೇತ್ರನು ಕಂಡುಹಿಡಿದನು.","ಅಂದ್ರೆಯನು ಅವನನ್ನು ಕಂಡುಹಿಡಿದನು."]],
  ["ಬೇತ್ಸಥ ಕೊಳ",["ಅದಕ್ಕೆ ಐದು ಮಂಟಪಗಳಿದ್ದವು.","ಆ ಮನುಷ್ಯನು ಮೂವತ್ತೆಂಟು ವರುಷ ರೋಗಿಯಾಗಿದ್ದನು."],["ಯೇಸು ಅವನನ್ನು ಸಂತೆಯ ದಿನದಲ್ಲಿ ಗುಣಪಡಿಸಿದನು.","ಅದು ಸಬ್ಬತ್ ದಿನವಾಗಿತ್ತು."]],
  ["ಸೌವಾರ್ತಿಕನಾದ ಫಿಲಿಪ್ಪ",["ಅವನು ಸಮಾರ್ಯದಲ್ಲಿ ಕ್ರಿಸ್ತನನ್ನು ಸಾರಿದನು.","ಐಥಿಯೋಪ್ಯದ ಕಂಚುಕಿಗೆ ಅವನು ಬಾಪ್ತಿಸ್ಮ ಮಾಡಿಸಿದನು."],["ಅವನು ಬೇತ್ಸಾಯಿದದ ಅಪೊಸ್ತಲನಾದ ಫಿಲಿಪ್ಪನು.","ಅವನು ಬೇರೊಬ್ಬ ಫಿಲಿಪ್ಪ; ಸೇವೆಗಾಗಿ ಆರಿಸಲ್ಪಟ್ಟ ಏಳು ಮಂದಿಯಲ್ಲಿ ಅವನು ಒಬ್ಬನು."]],
  ["ಕೊರ್ನೇಲ್ಯ",["ಅವನು ಇತಾಲ್ಯ ದಂಡಿನ ಶತಾಧಿಪತಿ.","ಅವನು ಜನರಿಗೆ ಬಹಳ ಧರ್ಮಮಾಡುತ್ತಿದ್ದನು."],["ಅವನು ಯೆರೂಸಲೇಮಿನಲ್ಲಿ ವಾಸವಾಗಿದ್ದನು.","ಅವನು ಕೈಸರೈಯದಲ್ಲಿ ವಾಸವಾಗಿದ್ದನು."]],
  ["ಅನನೀಯ ಸಪ್ಫೈರರು",["ಅವರು ಒಂದು ಸೊತ್ತನ್ನು ಮಾರಿದರು.","ಅವರು ಕ್ರಯದಲ್ಲಿ ಒಂದು ಭಾಗವನ್ನು ಉಳಿಸಿಕೊಂಡರು."],["ಸಪ್ಫೈರಳು ಪೇತ್ರನಿಗೆ ಸತ್ಯವನ್ನು ಹೇಳಿದಳು.","ಅವಳೂ ಸುಳ್ಳು ಹೇಳಿ ಬಿದ್ದು ಸತ್ತಳು."]],
  ["ಸೀಲ",["ಅವನು ಫಿಲಿಪ್ಪಿಯಲ್ಲಿ ಪೌಲನೊಂದಿಗೆ ಸೆರೆಯಲ್ಲಿದ್ದನು.","ಮಧ್ಯರಾತ್ರಿಯಲ್ಲಿ ಅವನು ಸ್ತುತಿಗೀತೆ ಹಾಡಿದನು."],["ನಂಬಿದ ಸೆರೆಮನೆಯ ಯಜಮಾನನು ಅವನೇ.","ಸೆರೆಮನೆಯ ಯಜಮಾನನು ಬೇರೊಬ್ಬನು; ನಾನು ಏನು ಮಾಡಬೇಕೆಂದು ಅವನು ಕೇಳಿದನು."]],
  ["ಗಮಲಿಯೇಲ",["ಅವನು ಧರ್ಮಶಾಸ್ತ್ರೋಪದೇಶಕನು.","ಅಪೊಸ್ತಲರ ಗೊಡವೆಗೆ ಹೋಗಬೇಡಿರಿ ಎಂದು ಸಭೆಗೆ ಸಲಹೆಕೊಟ್ಟನು."],["ಅವನು ಸದ್ದುಕಾಯನು.","ಅವನು ಫರಿಸಾಯನು."]],
  ["ಅಪೊಲ್ಲೋಸ",["ಅವನು ಅಲೆಕ್ಸಾಂದ್ರಿಯದಲ್ಲಿ ಹುಟ್ಟಿದವನು.","ಅಕ್ವಿಲ ಪ್ರಿಸ್ಕಿಲ್ಲರು ಅವನಿಗೆ ಇನ್ನೂ ಖಚಿತವಾಗಿ ಬೋಧಿಸಿದರು."],["ಅವನು ಪೌಲನೊಂದಿಗೆ ಗುಡಾರ ಮಾಡುವವನಾಗಿದ್ದನು.","ಅಕ್ವಿಲ ಪ್ರಿಸ್ಕಿಲ್ಲರು ಪೌಲನೊಂದಿಗೆ ಗುಡಾರ ಮಾಡುವವರಾಗಿದ್ದರು."]],
  ["ಯೂತಿಕ",["ಅವನು ಕಿಟಕಿಯಲ್ಲಿ ಕುಳಿತಿದ್ದನು.","ಅವನು ಮೂರನೆಯ ಮಾಳಿಗೆಯಿಂದ ಕೆಳಗೆ ಬಿದ್ದನು."],["ಪೇತ್ರನು ಪ್ರಸಂಗಿಸುತ್ತಿರುವಾಗ ಅವನಿಗೆ ನಿದ್ರೆ ಬಂತು.","ಪೌಲನು ಬಹಳ ಹೊತ್ತು ಪ್ರಸಂಗಿಸುತ್ತಿದ್ದನು."]],
  ["ಅರಸನಾದ ಅಗ್ರಿಪ್ಪ",["ಸ್ವಲ್ಪದರಲ್ಲೇ ನನ್ನನ್ನು ಕ್ರೈಸ್ತನನ್ನಾಗಿ ಮಾಡುವಿ ಎಂದು ಹೇಳಿದನು.","ಅವನು ಬೆರ್ನಿಕೆಯೊಂದಿಗೆ ಫೆಸ್ತನನ್ನು ನೋಡಲು ಬಂದನು."],["ಪೌಲನ ತಲೆ ಕಡಿಸಬೇಕೆಂದು ಆಜ್ಞಾಪಿಸಿದನು.","ಕೈಸರನಿಗೆ ಮನವಿ ಮಾಡದಿದ್ದರೆ ಪೌಲನನ್ನು ಬಿಡುಗಡೆ ಮಾಡಬಹುದಿತ್ತು ಎಂದನು."]],
  ["ರೋದೆ",["ಮಾರ್ಕನೆನಿಸಿಕೊಳ್ಳುವ ಯೋಹಾನನ ತಾಯಿಯಾದ ಮರಿಯಳ ಮನೆಯ ಹುಡುಗಿ.","ಅವಳು ಪೇತ್ರನ ಸ್ವರವನ್ನು ಗುರುತಿಸಿದಳು."],["ಅವಳು ತಕ್ಷಣ ಬಾಗಿಲನ್ನು ತೆರೆದು ಪೇತ್ರನನ್ನು ಒಳಗೆ ಕರೆದಳು.","ಸಂತೋಷದ ನಿಮಿತ್ತ ಅವಳು ಬಾಗಿಲನ್ನು ತೆರೆಯಲಿಲ್ಲ."]],
  ["ಪಂಚಾಶತ್ತಮ ದಿನ",["ಬಲವಾದ ಗಾಳಿ ಬೀಸುವಂಥ ಶಬ್ದವು ಉಂಟಾಯಿತು.","ಬೆಂಕಿಯಂತಿರುವ ವಿಭಾಗವಾದ ನಾಲಿಗೆಗಳು ಅವರ ಮೇಲೆ ಕೂತವು."],["ಆ ದಿನ ಸುಮಾರು ಮುನ್ನೂರು ಜನರು ಸೇರಿಸಲ್ಪಟ್ಟರು.","ಸುಮಾರು ಮೂರು ಸಾವಿರ ಜನರು ಸೇರಿಸಲ್ಪಟ್ಟರು."]]
];

